  const CH6_LESSONS=[{"id":"6.1","title":"Continuous Probability Foundations","skills":["C6.01","C6.02"],"objective":"Distinguish discrete from continuous random variables and explain why probability for a continuous variable is area, not the height of the density curve.","explain":["A discrete variable jumps between countable outcomes. A continuous variable can take any real value in an interval, so measurements such as time, length, height and volume are continuous.","For a continuous distribution the vertical axis is density f(x), not probability. Probability is the area under the density curve over an interval. The full area is 1.","A single point has zero width, so it has zero area. Therefore P(X=c)=0. That is also why P(X<c)=P(X≤c) for continuous X."],"visual":"continuum","say":"“Discrete means countable points. Continuous means any measured value in a range. For continuous variables, probability is area under the density curve, so one exact point has probability zero.”","check":{"q":"Which statement is correct for a continuous random variable X?","options":["P(X=4)=0","P(X=4)=f(4)","P(X=4) must be positive"],"answer":"P(X=4)=0","why":"An exact point has no width, so it contributes zero area."},"worked":{"title":"Why < and ≤ give the same continuous probability","steps":["Suppose we want P(X≤5).","Split it as P(X<5)+P(X=5).","For continuous X, P(X=5)=0.","Therefore P(X≤5)=P(X<5)."],"answer":"Including or excluding one boundary point does not change a continuous probability.","check":"If your reasoning depends on a positive probability at exactly one continuous value, stop and repair that idea."},"try":{"type":"choice","q":"Which event has the same probability as P(X<8) when X is continuous?","options":["P(X≤8)","P(X=8)","P(X>8)"],"answer":"P(X≤8)","solution":"Because P(X=8)=0, adding that single point changes no area."},"exit":"Move on when you can explain, without notes, why density height is not probability and why P(X=c)=0.","practiceId":"C6-Q01","sources":["2026 Chapter 6 slides §§ continuous foundations","Chapter 6 lecturer transcript: discrete vs continuous / probability as area","Semester 1 Final Boss hub used only as a checked explanation/layout donor"]},{"id":"6.2","title":"Normal Distribution","skills":["C6.03","C6.04","C6.05","C6.06","C6.07"],"objective":"Read normal notation, predict how μ and σ change the curve, recognise the standard normal distribution, and standardise X to Z.","explain":["The normal distribution is continuous, symmetric and bell-shaped. Its centre is μ. In a perfectly normal model, mean = median = mode.","In X~N(μ,σ²), the second parameter is variance. If you are given σ², take its square root before using the z-score formula.","Changing μ shifts the curve left or right without changing its basic shape. Increasing σ spreads the same total area over a wider range, so the curve becomes wider and flatter.","Any normal X can be translated to the standard normal Z~N(0,1) with z=(x−μ)/σ. A z-score tells you how many standard deviations x lies above or below μ."],"visual":"normalParams","say":"“Mu sets the centre. Sigma sets the spread. Standardising subtracts the mean and divides by the standard deviation, so z tells me how many standard deviations the value is from the mean.”","check":{"q":"If X~N(18,25), what standard deviation should you use?","options":["5","25","√18"],"answer":"5","why":"The notation gives variance σ²=25, so σ=√25=5."},"worked":{"title":"Standardise a value","steps":["Given X~N(100,50²) and x=200.","Identify μ=100 and σ=50.","Compute z=(200−100)/50.","z=2."],"answer":"x=200 is 2 standard deviations above the mean.","check":"A value above μ must produce a positive z-score; below μ must produce a negative one."},"try":{"type":"numeric","q":"If X~N(50,4²), what is z when x=42?","answer":-2,"tolerance":0.001,"solution":"z=(42−50)/4=−2. The negative sign makes sense because 42 is below the mean 50."},"exit":"Move on when you can look at N(μ,σ²), identify μ and σ correctly, predict the effect of changing each parameter, and standardise one value without help.","practiceId":"P-NUM-Z","sources":["2026 Chapter 6 slides pp. 1–2","2023/departmental Chapter 6 slides: normal shape and standardisation","Chapter 6 lecturer transcript"]},{"id":"6.3","title":"Normal Regions & Forward Probability","skills":["C6.08","C6.09","C6.10","C6.11"],"objective":"Translate “below”, “above” and “between” into the correct shaded region, standardise boundaries, and calculate the required normal area.","explain":["Do not begin with calculator buttons. First draw or identify the region in X-units. The wording determines the region.","Below / less than means the left cumulative area. Above / greater than means a right tail, so use 1−left area. Between means upper left-area minus lower left-area.","Then standardise any X boundary using z=(x−μ)/σ. The course Excel routes are NORM.DIST(x,μ,σ,TRUE) for X directly and NORM.S.DIST(z,TRUE) for Z."],"visual":"normalRegions","say":"“Below is left. Above is one minus left. Between is upper left area minus lower left area. I draw the region first, then standardise, then calculate.”","check":{"q":"Which expression gives a right-tail standard-normal probability P(Z>z)?","options":["1−Φ(z)","Φ(z)","Φ(z)−1"],"answer":"1−Φ(z)","why":"The cumulative function gives left area; the right tail is its complement."},"worked":{"title":"Official download-time example: P(X<18.6)","steps":["Given X~N(18,5²). We want the area left of 18.6.","Standardise: z=(18.6−18)/5=0.12.","Find Φ(0.12)=0.5478.","Interpret: about 54.78% of download times are below 18.6 seconds."],"answer":"P(X<18.6)=0.5478.","check":"18.6 is slightly above the mean, so a left-tail probability slightly above 0.5 is sensible."},"try":{"type":"numeric","q":"For the same X~N(18,5²), find P(X>18.6). Enter a decimal to 4 d.p.","answer":0.4522,"tolerance":0.00011,"solution":"Right tail = 1−0.5478=0.4522."},"exit":"Move on when you can identify left/right/between before touching the calculator and can explain why the numerical answer matches the shaded region.","practiceId":"C6-Q03","sources":["2026 Chapter 6 notes §1.3","Chapter 6 lecturer transcript download-time example","Tutorial 6 + solutions Q1–Q5","Chapter 6 Excel shortcuts"]},{"id":"6.4","title":"Inverse Normal & Percentiles","skills":["C6.12","C6.13","C6.14","C6.15","C6.16","C6.17"],"objective":"Recognise when probability is known but the boundary is unknown, convert wording to cumulative-left area, find z, and transform back to X.","explain":["Forward normal problems give x and ask for probability. Inverse normal problems give probability or percentile and ask for x.","The inverse tool expects cumulative area to the left. If the wording gives a right-tail percentage, convert it first. Example: top 10% means 10% to the right, so 90% to the left.","Find z from the cumulative-left probability, then return to original units with x=μ+zσ. Excel can do this directly with NORM.INV(prob,μ,σ), or use NORM.S.INV(prob) then back-transform."],"visual":"inverseNormal","say":"“Inverse normal means the area is known and the boundary is unknown. I convert everything to left area, find z, then use x equals mu plus z sigma.”","check":{"q":"The top 10% starts above x. What cumulative-left probability must go into the inverse function?","options":["0.90","0.10","0.05"],"answer":"0.90","why":"If 10% is above x, then 90% is below x."},"worked":{"title":"20th percentile of N(18,5²)","steps":["We need x with P(X<x)=0.20.","Inverse standard normal gives z≈−0.8416.","Back-transform: x=18+(−0.8416)(5).","x≈13.792 seconds."],"answer":"The 20th percentile is about 13.8 seconds.","check":"A 20th percentile must lie below the mean, so a negative z and x<18 are sensible."},"try":{"type":"numeric","q":"Tutorial-style: X~N(73,8²). Find the boundary exceeded by only 5% of values. Enter the boundary.","answer":86.16,"tolerance":0.03,"solution":"Only 5% above means cumulative-left area 0.95. z≈1.645, so x=73+1.645(8)=86.16."},"exit":"Move on when you can translate percentile/top/bottom wording into a left cumulative probability and perform the back-transform without being prompted.","practiceId":"C6-Q04","sources":["2026 Chapter 6 notes §1.3.2","Percentiles from normal distribution worked sheet","Tutorial 6 + solutions Q2–Q5","Chapter 6 Excel shortcuts"]},{"id":"6.5","title":"Evaluation of Normality","skills":["C6.18","C6.19","C6.20","C6.21","C6.22","C6.26"],"objective":"Judge whether data are approximately normal by integrating descriptive, empirical-rule and graphical evidence instead of relying on one indicator.","explain":["Real data are rarely perfectly normal. The task is usually to decide whether a normal approximation is reasonable.","Numerical evidence includes mean, median and mode for symmetry and the empirical 68–95–99.7 rule. Mean greater than median suggests right skew; mean less than median suggests left skew.","Graphical evidence includes histograms, frequency polygons, stem-and-leaf displays, boxplots and the normal probability plot. A normal probability plot should be approximately linear.","The strongest conclusion uses several indicators together. A bell-shaped histogram alone does not prove normality, and mean≈median alone does not prove normality."],"visual":"normality","say":"“Normality is a collective judgement. I check centre and symmetry, empirical-rule proportions, and plots. No single check proves the model.”","check":{"q":"Which is the strongest conclusion method?","options":["Use several numerical and graphical indicators together","Mean≈median proves normality","A bell-shaped histogram alone proves normality"],"answer":"Use several numerical and graphical indicators together","why":"The course notes and transcript require an integrated conclusion from multiple indicators."},"worked":{"title":"Small-sample empirical-rule evidence","steps":["A worked example has n=15.","Observed within 1s: 73% versus theoretical 68%.","Observed within 2s: 100% versus theoretical 95%.","Observed within 3s: 100% versus theoretical 99.7%.","For a small sample, these are treated as reasonably close; combine this with symmetry and plot evidence before concluding."],"answer":"The example is classified as approximately normal based on the collective evidence.","check":"Do not write “normal because 73%≈68%”. Your conclusion should explicitly combine the available evidence."},"try":{"type":"choice","q":"A dataset has mean≈median, but its histogram is strongly right-skewed. What is the best conclusion?","options":["Do not call it normal; the evidence conflicts","It is normal because mean≈median","Ignore the histogram"],"answer":"Do not call it normal; the evidence conflicts","solution":"One matching centre measure cannot override clear graphical non-normality."},"exit":"Move on when you can list at least three different normality checks and explain why the conclusion must use them collectively.","practiceId":"C6-Q06","sources":["2026 Chapter 6 notes §§1.4, pp. 8–13","Chapter 6 lecturer transcript normality discussion","Tutorial 6 Q18–Q20"]},{"id":"6.6","title":"Excel Normality Laboratory","skills":["C6.23","C6.24","C6.25","C6.26"],"objective":"Construct a normal probability plot correctly in Excel and combine it with descriptive/histogram evidence to reach a statistical conclusion.","explain":["The normal probability plot is built from ordered observed values and the theoretical standard-normal quantiles they should correspond to if the data were normal.","The course workflow is: sort X ascending → create index j → calculate αj=j/(n+1) → convert αj to Z with NORM.S.INV → scatterplot Z on the x-axis and ordered X on the y-axis → judge linearity.","This is a separate evidence channel from statistical understanding. Knowing the Excel clicks is not the same as knowing why a straight line supports normality."],"visual":"excelNormality","say":"“Sort X, number the rows j, calculate j over n plus one, turn each probability into Z with NORM.S.INV, plot Z horizontally and X vertically, then judge whether the points are roughly linear.”","check":{"q":"Which plotting position does the current Chapter 6 workflow use?","options":["j/(n+1)","j/n","(j−1)/n"],"answer":"j/(n+1)","why":"That is the explicit current course workflow and the supplied Excel solution uses it."},"worked":{"title":"Supplied commuting-time workbook (n=15)","steps":["For j=1: α=1/16=0.0625.","NORM.S.INV(0.0625)≈−1.5341.","The first ordered X is 24.6. Plot the point (Z,X)=(−1.5341,24.6).","Repeat through j=15, ending at α=15/16=0.9375 and Z≈1.5341.","Use a scatterplot and assess whether the cloud follows an approximately straight line."],"answer":"The plot is a theoretical-quantile check: approximate linearity supports normality.","check":"Axes matter: Z belongs on x, ordered X on y in the official workflow."},"try":{"type":"choice","q":"After sorting X and creating j, what Excel formula should convert α in D3 to its theoretical z-value?","options":["=NORM.S.INV(D3)","=NORM.S.DIST(D3,TRUE)","=NORM.INV(D3,0,1)"],"answer":"=NORM.S.INV(D3)","solution":"α is a cumulative probability, so you need the inverse standard-normal function."},"exit":"Move on when you can reconstruct the six-step normal-probability-plot workflow from memory and explain what linearity means.","practiceId":"C6-Q07","sources":["2026 Chapter 6 notes §1.4 step 3","Supplied Chapter 6 Excel examples (Solutions).xlsx · Normal plot sheet","T06-data.xlsx · Steel / Utility / Wait","Chapter 6 lecturer transcript normal-plot workflow"]},{"id":"6.7","title":"Uniform Distribution","skills":["C6.35","C6.36","C6.37","C6.38","C6.39","C6.40","C6.41"],"objective":"Recognise a uniform model, identify bounds a and b, use rectangle area for probabilities, and calculate the mean and spread.","explain":["A uniform distribution is continuous and rectangular. Every equal-width interval inside [a,b] has the same probability because the density height is constant.","The height is f(x)=1/(b−a). The height itself is not a probability; probability is rectangle area = width×height.","For c<d inside [a,b], P(c<X<d)=(d−c)/(b−a). The mean is (a+b)/2 and the standard deviation is sqrt((b−a)^2/12)."],"visual":"uniform","say":"“Uniform means a rectangle from a to b. Height is one over b minus a, but probability is area. Interval probability is interval width divided by total width.”","check":{"q":"For Uniform(a,b), what does 1/(b−a) represent?","options":["Density height","Every interval probability","The mean"],"answer":"Density height","why":"The probability requires area, so it also depends on interval width."},"worked":{"title":"Tutorial 6 Q8: Uniform(0,10), P(5<X<7)","steps":["Identify a=0, b=10.","Total width is 10. Target interval width is 7−5=2.","Probability=2/10=0.20.","Equivalent area method: height=1/10=0.1, area=2×0.1=0.20."],"answer":"P(5<X<7)=0.20.","check":"The interval uses 20% of the total horizontal width, so 0.20 is visually sensible."},"try":{"type":"numeric","q":"For X~Uniform(0,10), find P(2<X<3).","answer":0.1,"tolerance":0.0001,"solution":"The target width is 1 out of a total width 10, so probability=1/10=0.10."},"exit":"Move on when you can draw the rectangle, label a and b, explain why height is not probability, and solve an interval by area without memorising a special case.","practiceId":"C6-Q10","sources":["2026 Chapter 6 notes §§2.1–2.1.5","Uniform probabilities worked sheet","Tutorial 6 + solutions Q8–Q9","Chapter 6 lecturer transcript uniform explanation"]},{"id":"6.8","title":"Exponential Distribution","skills":["C6.42","C6.43","C6.44","C6.45","C6.46","C6.47","C6.48","C6.50"],"objective":"Recognise exponential waiting-time problems, interpret λ as a rate, align units, and solve left-, right- and between-probability questions.","explain":["The exponential distribution models continuous waiting time between events. It is right-skewed and starts at 0.","λ is a rate per unit time or opportunity, not the waiting time itself. Mean waiting time is 1/λ and variance is 1/λ².","Use P(X≤x)=1−e^(−λx) for a left tail and P(X≥x)=e^(−λx) for a right tail. For between events subtract two cumulative left areas.","Poisson and exponential share the same rate context: Poisson counts how many events occur in a fixed interval; exponential measures the time until/between events.","Before calculating, λ and x must use the same time unit."],"visual":"exponential","say":"“Poisson counts events. Exponential waits for the next event. Lambda is a rate, and lambda times time must use matching units.”","check":{"q":"Calls arrive at 12 per hour. The question asks for time until the next call. Which model?","options":["Exponential","Poisson","Uniform"],"answer":"Exponential","why":"The random object is waiting time, which is continuous."},"worked":{"title":"Toll plaza: 50 cars/min, next car within 3 seconds","steps":["Random object: waiting time, so use exponential.","λ=50 per minute. Convert 3 seconds to 0.05 minute.","P(X≤0.05)=1−e^(−50×0.05).","=1−e^(−2.5)≈0.9179."],"answer":"Probability ≈0.9179.","check":"With 50 arrivals per minute, a very short wait is quite likely, so a large probability makes sense."},"try":{"type":"numeric","q":"Calls arrive at 12 per hour. Find P(next call arrives within 3 minutes). Enter 4 d.p.","answer":0.4512,"tolerance":0.00015,"solution":"Convert λ=12/hour to 0.2/minute. P(X<3)=1−e^(−0.2×3)=1−e^(−0.6)≈0.4512."},"exit":"Move on when you can distinguish Poisson count from exponential wait and catch a rate/time unit mismatch before substituting.","practiceId":"C6-Q12","sources":["2026 Chapter 6 notes §§3.1–3.1.5","Exponential probabilities worked sheet","Tutorial 6 + solutions Q10–Q13","Chapter 6 lecturer transcript toll-plaza example"]},{"id":"6.9","title":"Inverse Exponential","skills":["C6.49","C6.50"],"objective":"Solve for an unknown waiting-time boundary when a cumulative or tail probability is given, and keep it conceptually separate from inverse normal.","explain":["Inverse exponential asks for time x rather than probability. Start from the exponential probability equation and solve for x using natural logarithms.","If P(X≤x)=α, then 1−e^(−λx)=α, so e^(−λx)=1−α and x=−ln(1−α)/λ.","If the question gives a right-tail probability q=P(X>x), it is even quicker: e^(−λx)=q, so x=−ln(q)/λ.","This is not NORM.INV. Exponential is asymmetric and uses ln, not z-scores."],"visual":"inverseExp","say":"“Inverse exponential means solve the exponential equation for time. Cumulative alpha gives x equals minus ln of one minus alpha over lambda.”","check":{"q":"For cumulative probability α, which boundary formula is correct?","options":["−ln(1−α)/λ","μ+zσ","ln(α)λ"],"answer":"−ln(1−α)/λ","why":"It comes directly from solving 1−e^(−λx)=α for x."},"worked":{"title":"80th percentile when λ=2 per week","steps":["Set P(X<x)=0.80.","1−e^(−2x)=0.80, so e^(−2x)=0.20.","Take ln: −2x=ln(0.20).","x=−ln(0.20)/2≈0.8047 weeks."],"answer":"P80≈0.8047 weeks.","check":"An 80th percentile is a positive waiting time. Substituting it back should give cumulative probability near 0.80."},"try":{"type":"numeric","q":"If X~Exp(λ=3) and P(X>x)=0.65, find x.","answer":0.1436,"tolerance":0.0002,"solution":"Right tail gives e^(−3x)=0.65. Thus x=−ln(0.65)/3≈0.1436."},"exit":"Move on when you can derive the inverse formula from the probability equation and know immediately that inverse normal tools do not apply.","practiceId":"C6-Q15","sources":["Chapter 6 lecturer transcript inverse-exponential extension","Exponential probabilities worked sheet","2026 Chapter 6 content architecture"]},{"id":"6.10","title":"Normal Approximation to the Binomial","skills":["C6.27","C6.28","C6.29","C6.30","C6.31","C6.32","C6.33","C6.34"],"objective":"Decide when the normal approximation is allowed, construct the approximate normal model, apply the correct continuity correction, and calculate the probability.","explain":["The binomial distribution is discrete, but for sufficiently large expected success and failure counts its shape can be approximated by a normal curve.","Current Chapter 6 conditions are nπ>5 and n(1−π)>5. If either fails, do not use this approximation.","The approximating normal model has μ=nπ and σ=sqrt(nπ(1−π)).","Because the binomial lives on integer points while the normal curve is continuous, we use a ±0.5 continuity correction to preserve the area around each integer.","Exact x becomes x−0.5<Xa<x+0.5. X≤x becomes Xa<x+0.5. X≥x becomes Xa>x−0.5. Strict inequalities first need translation to the adjacent inclusive integer event."],"visual":"binomApprox","say":"“First check n pi and n one minus pi are both greater than five. Then mean is n pi, SD is square root n pi one minus pi, continuity-correct the integer boundary by half, then standardise.”","check":{"q":"Which continuous event approximates P(X≥25)?","options":["P(Xa>24.5)","P(Xa>25.5)","P(Xa<24.5)"],"answer":"P(Xa>24.5)","why":"The integer 25 owns the continuous slice from 24.5 to 25.5, so “25 or more” starts at 24.5."},"worked":{"title":"Tutorial 6 Q14: n=100, π=0.20, approximate P(X=25)","steps":["Check: nπ=20>5 and n(1−π)=80>5.","Approximate model: μ=20, σ=sqrt(16)=4.","Continuity correction: P(X=25)≈P(24.5<Xa<25.5).","zL=(24.5−20)/4=1.125≈1.13; zU=(25.5−20)/4=1.375≈1.38.","Probability≈Φ(1.38)−Φ(1.13)=0.9162−0.8708=0.0454."],"answer":"P(X=25)≈0.0454.","check":"Without the ±0.5 slice, a continuous model would assign zero probability to exactly 25."},"try":{"type":"choice","q":"For n=100 and π=0.20, how should P(X<25) be continuity-corrected?","options":["P(Xa<24.5)","P(Xa<25.5)","P(Xa>24.5)"],"answer":"P(Xa<24.5)","solution":"X<25 means X≤24 in the discrete model, so the corrected boundary is 24.5."},"exit":"Move on when you can do the two >5 checks, construct μ and σ, and continuity-correct =, <, ≤, > and ≥ without a lookup table.","practiceId":"C6-Q09","sources":["2026 Chapter 6 notes §§1.5, pp. 14–16","Normal approximation handwritten example","Tutorial 6 + solutions Q14–Q17","Chapter 6 lecturer transcript overbooking / continuity-correction explanation"]}];
  const CH6_LEARN_KEY='SDS188_CH6_LEARN_CANDIDATE_UI_V1';
  function ch6LearnState(){try{const x=JSON.parse(localStorage.getItem(CH6_LEARN_KEY)||'{}');return{active:x.active||'6.1',checks:x.checks||{},tries:x.tries||{},visited:x.visited||{}}}catch(_){return{active:'6.1',checks:{},tries:{},visited:{}}}}
  function saveCh6LearnState(s){localStorage.setItem(CH6_LEARN_KEY,JSON.stringify(s))}
  function lessonById(id){return CH6_LESSONS.find(x=>x.id===id)}
  function lessonReady(id){const s=ch6LearnState();return Boolean(s.checks[id]&&s.tries[id])}
  function lessonPct(){return Math.round(CH6_LESSONS.filter(x=>lessonReady(x.id)).length/CH6_LESSONS.length*100)}
  function sourceList(items){return `<p class="lesson-source"><strong>Lesson sources:</strong> ${items.map(esc).join(' · ')}</p>`}
  function renderLessonVisual(l){
    if(l.visual==='continuum')return `<div class="visual-compare"><div class="visual-panel"><div class="big">DISCRETE</div><p>Countable outcomes</p><div class="dotline"><span class="dot" style="left:15%"></span><span class="dot" style="left:50%"></span><span class="dot" style="left:85%"></span></div><small>1, 2, 3 … distinct points</small></div><div class="visual-arrow">→</div><div class="visual-panel"><div class="big">CONTINUOUS</div><p>Any measured value in an interval</p><div class="continuum"></div><small>1.5, 1.6, 1.99999…</small></div></div><div style="margin-top:1rem"><span class="point-zero">Single point = zero width = zero area → P(X=c)=0</span></div>`;
    if(l.visual==='normalParams')return `<svg class="normal-svg" viewBox="0 0 700 220" role="img" aria-label="Normal curves showing centre and spread"><line x1="40" y1="190" x2="660" y2="190" stroke="#493f39" stroke-width="2"/><path d="M70 190 C150 188 195 65 300 42 C405 65 450 188 530 190" fill="none" stroke="#7a2436" stroke-width="5"/><path d="M170 190 C240 185 270 95 350 65 C430 95 460 185 530 190" fill="none" stroke="#35627a" stroke-width="4" stroke-dasharray="8 6"/><line x1="300" y1="42" x2="300" y2="190" stroke="#7a2436" stroke-width="2" stroke-dasharray="5 5"/><line x1="350" y1="65" x2="350" y2="190" stroke="#35627a" stroke-width="2" stroke-dasharray="5 5"/><text x="272" y="210" fill="#7a2436" font-size="14">μ shifts centre</text><text x="365" y="90" fill="#35627a" font-size="14">σ changes spread</text></svg><div class="param-grid"><div class="param-card"><strong>μ changes</strong>Whole curve shifts left/right.</div><div class="param-card"><strong>σ increases</strong>Curve gets wider and flatter.</div><div class="param-card"><strong>Z scale</strong>Mean 0, SD 1; same shape, new units.</div></div>`;
    if(l.visual==='normalRegions')return `<div class="region-demo-controls"><button type="button" data-learn-region="left" class="active">BELOW / LEFT</button><button type="button" data-learn-region="right">ABOVE / RIGHT</button><button type="button" data-learn-region="between">BETWEEN</button></div><div class="region-lab left learn-region" id="ch6-region-demo"><div class="shade"></div><span class="boundary" style="left:37%">boundary</span></div><div class="area-flow"><div><strong>LEFT</strong>Φ(z)</div><div><strong>RIGHT</strong>1−Φ(z)</div><div><strong>BETWEEN</strong>Φ(zU)−Φ(zL)</div></div>`;
    if(l.visual==='inverseNormal')return `<div class="formula-flow"><span><b>Known area</b><br>e.g. 0.80 left</span><b>→</b><span><b>Inverse</b><br>z=NORM.S.INV(0.80)</span><b>→</b><span><b>Back-transform</b><br>x=μ+zσ</span></div><div class="lesson-callout"><strong>Right-tail translation:</strong> top 10% → 0.10 right → 0.90 left before using the inverse function.</div>`;
    if(l.visual==='normality')return `<div class="evidence-grid"><div class="evidence-card"><strong>1 · Centre / symmetry</strong><br>mean, median, mode; skew direction</div><div class="evidence-card"><strong>2 · Empirical rule</strong><br>about 68%, 95%, 99.7%</div><div class="evidence-card"><strong>3 · Graphs</strong><br>histogram, boxplot, normal plot</div></div><div class="empirical"><span>68% within ±1σ</span><span>95% within ±2σ</span><span>99.7% within ±3σ</span></div><div class="lesson-callout trap"><strong>Trap:</strong> no single indicator proves normality.</div>`;
    if(l.visual==='excelNormality')return `<div class="excel-route">SORT X ↑ → j = 1…n → α = j/(n+1) → Z = NORM.S.INV(α) → SCATTER: x-axis Z, y-axis ordered X → JUDGE LINEARITY</div><table class="excel-mini"><thead><tr><th>j</th><th>ordered X</th><th>α=j/16</th><th>Z</th></tr></thead><tbody><tr><td>1</td><td>24.60</td><td>0.0625</td><td>−1.5341</td></tr><tr><td>2</td><td>27.43</td><td>0.1250</td><td>−1.1503</td></tr><tr><td>3</td><td>27.93</td><td>0.1875</td><td>−0.8871</td></tr><tr><td>8</td><td>31.93</td><td>0.5000</td><td>0.0000</td></tr><tr><td>15</td><td>39.47</td><td>0.9375</td><td>1.5341</td></tr></tbody></table><div class="lesson-callout good"><strong>Excel formula pattern:</strong> if α is in D3, use <code>=NORM.S.INV(D3)</code>.</div>`;
    if(l.visual==='uniform')return `<div class="uniform-box"><div class="rect"></div><div class="ushade"></div><span class="ua">a</span><span class="ub">b</span><span class="uc">c</span><span class="ud">d</span><span class="height-label">height = 1/(b−a)</span></div><div class="formula-flow"><span>probability</span><b>=</b><span>rectangle width</span><b>×</b><span>density height</span></div>`;
    if(l.visual==='exponential')return `<svg class="exp-svg" viewBox="0 0 700 220" role="img" aria-label="Right-skewed exponential density"><line x1="45" y1="190" x2="660" y2="190" stroke="#493f39" stroke-width="2"/><line x1="45" y1="25" x2="45" y2="190" stroke="#493f39" stroke-width="2"/><path d="M45 35 C130 90 170 145 260 166 C360 188 500 190 650 190" fill="none" stroke="#35627a" stroke-width="5"/><text x="53" y="28" fill="#35627a" font-size="14">high density near 0</text><text x="480" y="178" fill="#35627a" font-size="14">long right tail</text></svg><div class="poisson-exp"><div><strong>POISSON</strong>How many events in a fixed interval?<br><em>discrete count</em></div><div><strong>EXPONENTIAL</strong>How long until / between events?<br><em>continuous time</em></div></div>`;
    if(l.visual==='inverseExp')return `<div class="formula-flow"><span><b>P(X≤x)=α</b></span><b>→</b><span>1−e<sup>−λx</sup>=α</span><b>→</b><span>e<sup>−λx</sup>=1−α</span><b>→</b><span><b>x=−ln(1−α)/λ</b></span></div><div class="lesson-callout trap"><strong>Do not use NORM.INV here.</strong> Exponential inverse problems use the logarithm because the model is not normal.</div>`;
    if(l.visual==='binomApprox')return `<div class="binom-bridge"><div class="binom-side"><strong>BINOMIAL · discrete</strong>Integer outcomes; exact point has positive probability.</div><div class="visual-arrow">→ ±0.5 →</div><div class="binom-side"><strong>NORMAL · continuous</strong>Areas on a continuum; exact point has zero probability.</div></div><table class="continuity-table"><thead><tr><th>Discrete event</th><th>Normal approximation</th></tr></thead><tbody><tr><td>X=x</td><td>x−0.5 &lt; Xa &lt; x+0.5</td></tr><tr><td>X≤x</td><td>Xa &lt; x+0.5</td></tr><tr><td>X≥x</td><td>Xa &gt; x−0.5</td></tr><tr><td>X&lt;x</td><td>X≤x−1 → Xa &lt; x−0.5</td></tr><tr><td>X&gt;x</td><td>X≥x+1 → Xa &gt; x+0.5</td></tr></tbody></table>`;
    return '';
  }
  function renderMiniCheck(l){const c=l.check;return `<fieldset class="learn-check" id="learn-check-${esc(l.id)}"><legend>TINY KNOWLEDGE CHECK · FORMATIVE ONLY</legend><p><strong>${esc(c.q)}</strong></p>${c.options.map(o=>`<label><input type="radio" name="lc-${esc(l.id)}" value="${esc(o)}"> ${esc(o)}</label>`).join('')}<button class="secondary" type="button" data-learn-check="${esc(l.id)}">CHECK</button><div class="learn-feedback" id="lc-feedback-${esc(l.id)}" aria-live="polite"></div></fieldset>`}
  function renderTry(l){const t=l.try;let control='';if(t.type==='numeric')control=`<input class="learn-numeric" id="lt-input-${esc(l.id)}" type="number" step="any" inputmode="decimal">`;else control=t.options.map(o=>`<label><input type="radio" name="lt-${esc(l.id)}" value="${esc(o)}"> ${esc(o)}</label>`).join('');return `<div class="lesson-block lesson-try"><h3>YOUR TURN · NO MASTERY CREDIT HERE</h3><p><strong>${esc(t.q)}</strong></p>${t.type==='choice'?`<fieldset class="learn-check" style="margin:.6rem 0">${control}</fieldset>`:control}<div class="question-actions"><button class="primary" type="button" data-learn-try="${esc(l.id)}">CHECK MY ANSWER</button><button class="secondary" type="button" data-learn-reveal="${esc(l.id)}">REVEAL WORKED SOLUTION</button></div><div class="learn-feedback" id="lt-feedback-${esc(l.id)}" aria-live="polite"></div><div class="notice" id="lt-solution-${esc(l.id)}" hidden><strong>Worked solution:</strong> ${esc(t.solution)}</div></div>`}
  function renderCh6Roadmap(active){const s=ch6LearnState(),pct=lessonPct();return `<div class="learn-candidate-banner"><strong>CHAPTER 6 TEACHING-LAYER CANDIDATE</strong><br>This fixes the old static-box Learn experience. Lesson checks are formative UI only and <strong>do not change mastery</strong>. Formal evidence still comes from the existing Practise / Retrieval / Mixed / Timed engine.<div class="learn-progress-strip"><span>Formative lesson readiness: <strong>${pct}%</strong></span><div class="bar"><div class="fill" style="width:${pct}%"></div></div><span>${CH6_LESSONS.filter(x=>lessonReady(x.id)).length}/${CH6_LESSONS.length} checks + your-turns passed</span></div></div><div class="learn-roadmap" aria-label="Chapter 6 lesson roadmap">${CH6_LESSONS.map(x=>`<button type="button" data-open-ch6-lesson="${x.id}" aria-current="${x.id===active?'step':'false'}"><span class="lesson-code">${x.id}</span><span class="lesson-name">${esc(x.title)}</span><span class="lesson-state ${lessonReady(x.id)?'passed':''}">${lessonReady(x.id)?'FORMATIVE READY':'OPEN LESSON'}</span></button>`).join('')}</div>`}
  function renderCh6Lesson(id){const l=lessonById(id)||CH6_LESSONS[0],s=ch6LearnState();s.active=l.id;s.visited[l.id]=true;saveCh6LearnState(s);const idx=CH6_LESSONS.indexOf(l),prev=CH6_LESSONS[idx-1],next=CH6_LESSONS[idx+1];return `<article class="learn-lesson" id="ch6-active-lesson"><div class="learn-lesson-head"><div><div class="lesson-kicker">Chapter 6 · guided lesson ${idx+1} of ${CH6_LESSONS.length}</div><h2>${esc(l.id)} · ${esc(l.title)}</h2><p class="muted">Explanation → visual intuition → say aloud → tiny check → worked example → your turn → exit criterion</p></div><div class="lesson-skill-list">${l.skills.map(x=>`<span>${esc(x)} · ${esc(getSkillState(x))}</span>`).join('')}</div></div><div class="lesson-block lesson-objective"><h3>WHAT YOU'RE LEARNING</h3><p>${esc(l.objective)}</p></div><div class="lesson-block lesson-explain"><h3>EXPLANATION</h3>${l.explain.map(p=>`<p>${esc(p)}</p>`).join('')}</div><div class="lesson-block lesson-visual"><h3>SEE IT</h3>${renderLessonVisual(l)}</div><div class="lesson-block lesson-say"><h3>SAY THIS ALOUD</h3><p class="say-script">${esc(l.say)}</p><div class="lesson-callout"><strong>Rule:</strong> close or cover this sentence and say the idea again in your own words. Reading it silently is not the task.</div></div>${renderMiniCheck(l)}<div class="lesson-block lesson-worked"><h3>WORKED EXAMPLE · RECOGNISE → REPRESENT → SELECT → EXECUTE → INTERPRET → VERIFY</h3><h4>${esc(l.worked.title)}</h4><ol class="worked-steps">${l.worked.steps.map(x=>`<li><span>${esc(x)}</span></li>`).join('')}</ol><div class="lesson-callout good"><strong>Result:</strong> ${esc(l.worked.answer)}</div><div class="lesson-callout"><strong>Verify:</strong> ${esc(l.worked.check)}</div></div>${renderTry(l)}<div class="lesson-block lesson-exit"><h3>EXIT CRITERION</h3><p><strong>${esc(l.exit)}</strong></p><p class="compact">Passing the formative check helps you decide whether to move on. It is still <strong>not mastery evidence</strong>.</p></div>${sourceList(l.sources)}<div class="lesson-nav"><div>${prev?`<button class="secondary" type="button" data-open-ch6-lesson="${prev.id}">← ${esc(prev.id)} ${esc(prev.title)}</button>`:''}</div><div class="actions"><button class="learn-practice-btn" type="button" data-practice-ch6="${esc(l.practiceId)}">PRACTISE THIS SKILL IN THE EVIDENCE ENGINE</button>${next?`<button class="primary" type="button" data-open-ch6-lesson="${next.id}">NEXT → ${esc(next.id)} ${esc(next.title)}</button>`:`<button class="primary" type="button" data-finish-ch6-lessons="1">NEXT → RECOGNITION & MIXED PRACTICE</button>`}</div></div></article>`}
  function renderChapter6Learn(){const host=document.getElementById('chapter-content'),s=ch6LearnState(),active=lessonById(s.active)?s.active:'6.1';host.innerHTML=`${renderCh6Roadmap(active)}${renderCh6Lesson(active)}<div class="post-learn-path"><h3>After 6.10: remove the lesson support</h3><div class="spine"><span>6.R RECOGNISE</span><span>6.M MIX</span><span>6.B FINAL BOSS</span><span>6.X REPAIR</span></div><p>The old Semester 1 Final Boss hub is used as a content/design donor only. Current 2026 Chapter 6 sources control the academic content. The existing v1.3.1 mastery, retrieval, repair and timed engines remain the evidence layer.</p></div>`;bindCh6LearnUI()}
  function openCh6Lesson(id){const s=ch6LearnState();s.active=id;saveCh6LearnState(s);renderChapter6Learn();document.getElementById('ch6-active-lesson')?.scrollIntoView({behavior:'smooth',block:'start'})}
  function bindCh6LearnUI(){document.querySelectorAll('[data-open-ch6-lesson]').forEach(b=>b.onclick=()=>openCh6Lesson(b.dataset.openCh6Lesson));document.querySelectorAll('[data-learn-region]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-learn-region]').forEach(x=>x.classList.toggle('active',x===b));const r=document.getElementById('ch6-region-demo');if(r)r.className=`region-lab ${b.dataset.learnRegion} learn-region`});document.querySelectorAll('[data-learn-check]').forEach(b=>b.onclick=()=>checkCh6Mini(b.dataset.learnCheck));document.querySelectorAll('[data-learn-try]').forEach(b=>b.onclick=()=>checkCh6Try(b.dataset.learnTry));document.querySelectorAll('[data-learn-reveal]').forEach(b=>b.onclick=()=>{const p=document.getElementById(`lt-solution-${b.dataset.learnReveal}`);if(p)p.hidden=false});document.querySelectorAll('[data-practice-ch6]').forEach(b=>b.onclick=()=>{showView('practise');document.getElementById('filter-chapter').value='6';document.getElementById('filter-support').value='4';renderQuestion(b.dataset.practiceCh6,{support:4,attemptContext:'familiar_application'})});document.querySelectorAll('[data-finish-ch6-lessons]').forEach(b=>b.onclick=()=>{showView('practise');document.getElementById('filter-chapter').value='6';document.getElementById('filter-support').value='5';loadPractice()})}
  function checkCh6Mini(id){const l=lessonById(id),chosen=document.querySelector(`input[name="lc-${CSS.escape(id)}"]:checked`)?.value,fb=document.getElementById(`lc-feedback-${id}`);if(!chosen){fb.textContent='Choose an answer first.';fb.className='learn-feedback bad';return}const ok=chosen===l.check.answer;fb.textContent=(ok?'Correct. ':'Not yet. ')+l.check.why;fb.className=`learn-feedback ${ok?'good':'bad'}`;const s=ch6LearnState();s.checks[id]=ok;saveCh6LearnState(s)}
  function checkCh6Try(id){const l=lessonById(id),t=l.try,fb=document.getElementById(`lt-feedback-${id}`);let ok=false;if(t.type==='numeric'){const v=parseFloat(document.getElementById(`lt-input-${id}`)?.value);if(Number.isNaN(v)){fb.textContent='Enter a numeric answer first.';fb.className='learn-feedback bad';return}ok=Math.abs(v-t.answer)<=Number(t.tolerance||1e-9)}else{const v=document.querySelector(`input[name="lt-${CSS.escape(id)}"]:checked`)?.value;if(!v){fb.textContent='Choose an answer first.';fb.className='learn-feedback bad';return}ok=v===t.answer}fb.textContent=ok?'Correct. Formative try passed — now explain the method aloud.':'Not yet. Re-check the representation and method before revealing the solution.';fb.className=`learn-feedback ${ok?'good':'bad'}`;const s=ch6LearnState();s.tries[id]=ok;saveCh6LearnState(s)}
  function runCh6LearnQATests(){const r=[],a=(name,pass,detail='')=>r.push({name,pass:Boolean(pass),detail});a('10 guided Chapter 6 lessons',CH6_LESSONS.length===10,CH6_LESSONS.length);a('Lesson IDs 6.1–6.10',CH6_LESSONS.every((x,i)=>x.id===`6.${i+1}`));a('All practice targets exist',CH6_LESSONS.every(x=>Boolean(taskById(x.practiceId))));a('All mapped skills exist',CH6_LESSONS.every(x=>x.skills.every(id=>Boolean(SKILLS[id]))));a('All lessons have learning cycle fields',CH6_LESSONS.every(x=>x.objective&&x.explain?.length&&x.say&&x.check&&x.worked&&x.try&&x.exit));a('Formative state key separate from engine state',CH6_LEARN_KEY!==STORAGE_KEY);a('No Chapter 6 lesson is provisional',CH6_LESSONS.every(x=>x.skills.every(id=>SKILLS[id].status==='ACTIVE')));return r}


  /* ═══════════════════════════════════════════════════════════
     CHAPTER 9 GUIDED LEARN — current-source teaching layer.
     Source status: SOURCE_READY because the supplied official
     2023 deck was confirmed by the user as the official 2026 deck.
     Formative lesson checks remain separate from mastery evidence.
  ═══════════════════════════════════════════════════════════ */
  const CH9_LESSONS=[{"id":"9.1","title":"Hypothesis Foundations","skills":["C9.01","C9.02","C9.03","C9.04","C9.05","C9.06"],"objective":"Build H0 and H1 around a population parameter, start from the H0 assumption, and use the source-approved decision language.","explain":["A hypothesis is a claim about a population parameter such as the population mean μ or population proportion π. The sample statistic is evidence; it is not what H0 is written about.","H0 represents the claim/status quo to be validated and carries equality in the SDS188 treatment. H1 is mutually exclusive and challenges H0.","Testing begins by assuming H0 is true — the slides use the “innocent until proven guilty” analogy — and then asks whether the sample evidence is sufficiently inconsistent with that assumption.","The source explicitly warns that H0 is never accepted. Your statistical decision is “reject H0” or “do not reject H0”."],"visual":"foundations","say":"“My hypotheses are about a population parameter. I assume H0 is true, use the sample as evidence, and I either reject H0 or do not reject H0 — I never accept H0.”","check":{"q":"Which conclusion is valid source language?","options":["Do not reject H0","Accept H0","Prove H0 true"],"answer":"Do not reject H0","why":"The Chapter 9 deck explicitly states that H0 is never accepted."},"worked":{"title":"Turn a claim into hypotheses","steps":["Claim: the population mean fill is 500 ml.","Parameter is μ, not X̄.","Write H0: μ=500.","If the research question asks whether the mean differs, write H1: μ≠500.","Begin analysis under the assumption H0 is true."],"answer":"H0: μ=500; H1: μ≠500.","check":"Both statements concern μ and are mutually exclusive."},"try":{"type":"choice","q":"A company claims the population mean trip time is 110 minutes. Which H0 is correctly written?","options":["H0: μ=110","H0: X̄=110","H0: μ≠110"],"answer":"H0: μ=110","solution":"H0 is written about the population parameter μ and includes equality."},"exit":"Move on when you can write H0/H1 from wording and automatically say “reject” or “do not reject,” never “accept.”","practiceId":"C9-Q01","sources":["Official Chapter 9 deck pp. 4–10","SDS Tutorial 9 Q1–3"]},{"id":"9.2","title":"Decision Risk: α, β & Power","skills":["C9.07","C9.08","C9.09","C9.10","C9.11","C9.12"],"objective":"Understand the two possible testing errors and predict how α, β, power, effect size, variance and n move together.","explain":["Type I error means rejecting H0 when H0 is true. Its probability is α, the significance level.","Type II error means not rejecting H0 when H0 is false. Its probability is β. Power is 1−β: the probability of rejecting a false H0.","The confidence coefficient is 1−α. Type I and Type II errors cannot occur in the same test outcome because H0 cannot simultaneously be true and false.","For fixed n, reducing α makes rejection harder and β increases. Power rises when the true parameter is farther from the null value or n increases; larger variance makes detection harder and increases β."],"visual":"errorMatrix","say":"“Alpha is the chance I reject a true H0. Beta is the chance I fail to reject a false H0. Power is one minus beta. With fixed n, lowering alpha raises beta.”","check":{"q":"For fixed n, if α falls from .05 to .01, what happens to β?","options":["β increases","β decreases","β becomes α"],"answer":"β increases","why":"A stricter rejection region lowers Type I risk but raises Type II risk for a fixed design."},"worked":{"title":"Why distance from μ0 changes power","steps":["Suppose H0: μ=100.","A true μ=90 is 10 units from the null.","A true μ=75 is 25 units from the null.","The farther alternative creates more separation between the sampling distributions.","Therefore β is smaller and power larger at μ=75 than at μ=90."],"answer":"Closer alternatives are harder to detect; farther alternatives have higher power.","check":"This is exactly the logic behind Tutorial 9 Q3."},"try":{"type":"choice","q":"Which change, all else fixed, increases power?","options":["Increase n","Increase variance","Move the true mean closer to μ0"],"answer":"Increase n","solution":"A larger n reduces the sampling spread, so a false H0 is easier to detect."},"exit":"Move on when you can draw the 2×2 truth/decision table from memory and predict the direction of β and power changes.","practiceId":"C9-Q02","sources":["Official Chapter 9 deck: Type I/II error and power sections","SDS Tutorial 9 Q1–3, Q21–22"]},{"id":"9.3","title":"Tails, α & Rejection Regions","skills":["C9.13","C9.14","C9.15","C9.16"],"objective":"Let H1 determine the rejection tail and place α correctly before looking up a critical value.","explain":["The direction is determined by H1, not by the sign of the sample result.","H1: parameter≠value gives a two-tail test. H1: parameter<value gives a lower-tail test. H1: parameter>value gives an upper-tail test.","For a two-tail test, divide α equally: α/2 in each tail. For a one-tail test, place the full α in the one rejection tail.","Always sketch or state the rejection region before calculating the test statistic."],"visual":"tails","say":"“Not equal means two tails. Less than means lower tail. Greater than means upper tail. Two tails split alpha; one tail gets all alpha.”","check":{"q":"H1: μ>500 means which test?","options":["Upper-tail","Lower-tail","Two-tail"],"answer":"Upper-tail","why":"The alternative points to values greater than the null value."},"worked":{"title":"Tutorial 9 Q4 critical region","steps":["Two-tail test and α=.10.","Split α: .05 per tail.","The standard-normal cutoffs are approximately ±1.645.","Reject H0 if Z<−1.645 or Z>1.645."],"answer":"Rejection region: Z<−1.645 or Z>1.645.","check":"The middle non-rejection area is 0.90."},"try":{"type":"choice","q":"For a lower-tail test at α=.01, where is the rejection region?","options":["Entire α=.01 in the left tail","α/2 in both tails","Entire α=.01 in the right tail"],"answer":"Entire α=.01 in the left tail","solution":"One-tail means no split; “less than” points left."},"exit":"Move on when you can see H1 and immediately name the tail, allocate α and describe the rejection region.","practiceId":"C9-Q04","sources":["Official Chapter 9 deck: one-tail versus two-tail slides","SDS Tutorial 9 Q4–6"]},{"id":"9.4","title":"Mean Test — σ Known: Z Critical-Value","skills":["C9.17","C9.18","C9.19"],"objective":"Recognise a known-σ one-sample mean test, compute Z, and make the critical-value decision.","explain":["When the question tests a population mean μ and the population standard deviation σ is known, the Chapter 9 route is a Z test.","Under H0, the sample mean is compared with μ0 using its standard error σ/√n. The test statistic is Z=(X̄−μ0)/(σ/√n).","The critical value(s) come from α and the tail already chosen from H1. If Zcalc lands in the rejection region, reject H0; otherwise do not reject H0.","Finish with a sentence about the population claim — not just “reject”."],"visual":"zRoute","say":"“Mean plus known population sigma means Z. I use x-bar minus mu-zero over sigma divided by square root n, then compare with the rejection region set by H1 and alpha.”","check":{"q":"A mean is tested and σ is known. Which reference test does the source select?","options":["Z test","Student t test","Proportion Z test"],"answer":"Z test","why":"The deck’s technique-selection branch uses Z when population σ is known."},"worked":{"title":"Tutorial 9 paint cans","steps":["H0: μ=3.75; H1: μ≠3.75; α=.01.","σ=.08, n=50, X̄=3.73.","SE=.08/√50≈.011314.","Z=(3.73−3.75)/.011314≈−1.768.","Two-tail α=.01 gives critical values about ±2.576.","−1.768 is not in either rejection tail."],"answer":"Do not reject H0 at the 1% significance level.","check":"The test statistic is not extreme enough for the strict .01 two-tail rejection region."},"try":{"type":"numeric","q":"ATM example: μ0=500, σ=120, n=36, X̄=550. What is Zcalc?","answer":2.5,"tolerance":0.001,"solution":"SE=120/6=20; Z=(550−500)/20=2.5."},"exit":"Move on when you can identify known σ → Z and execute hypotheses → tail → SE → Z → critical comparison → contextual conclusion.","practiceId":"C9-Q10","sources":["Official Chapter 9 deck: Z-test critical-value workflow","SDS Tutorial 9 Q10–11"]},{"id":"9.5","title":"Z Test — p-Value + Excel","skills":["C9.20","C9.21","C9.22","C9.23","C9.24"],"objective":"Understand what the p-value means, calculate it for the correct tail, compare it with α, and reconstruct the deck’s Excel route.","explain":["The deck defines the p-value as the probability, assuming H0 is true, of obtaining a test statistic equal to or more extreme than the observed one.","Decision rule: if p<α, reject H0; if p≥α, do not reject H0.","Two-tail Z p-values use both tails. The source Excel formula is (1−NORM.S.DIST(ABS(Zcalc),TRUE))*2. A directed one-tail p-value uses only the tail specified by H1.","A p-value is not the probability that H0 is true. It is calculated under the assumption that H0 is true."],"visual":"pvalue","say":"“The p-value is an extremeness probability under H0. If p is smaller than alpha I reject H0; otherwise I do not reject H0.”","check":{"q":"If p=.032 and α=.05, what is the decision?","options":["Reject H0","Do not reject H0","Accept H0"],"answer":"Reject H0","why":"p<α."},"worked":{"title":"Tutorial 9 Q7","steps":["Two-tail test with Z=2.00.","One upper tail beyond 2.00 is about .02275.","Two-tail p≈2(.02275)=.0455.","Compare .0455 with α=.05.",".0455<.05, so reject H0."],"answer":"p≈.0455; reject H0 at α=.05.","check":"Two-tail means count equally extreme results in both directions."},"try":{"type":"numeric","q":"Lower-tail test with Z=−1.38. Enter the p-value to 4 d.p.","answer":0.0838,"tolerance":0.0002,"solution":"For a lower-tail test, p=Φ(−1.38)≈.0838; there is no doubling."},"exit":"Move on when you can explain the p-value in words, choose one-tail versus two-tail area, and reconstruct the source Excel formula without copying it.","practiceId":"C9-Q07","sources":["Official Chapter 9 deck: p-value definition and Excel Z workflow","SDS Tutorial 9 Q7–10"]},{"id":"9.6","title":"Two-Tail Z Test ↔ Confidence Interval","skills":["C9.25"],"objective":"Use the source’s equivalence between a two-tail Z test and the same-level confidence interval as a conceptual cross-check.","explain":["The Chapter 9 deck explicitly links a two-tail hypothesis test with the confidence interval built at confidence level 1−α.","If the hypothesised μ0 lies outside that interval, the two-tail test rejects H0 at significance α. If μ0 lies inside the interval, the test does not reject H0.","This is a cross-check of the same inferential evidence; it does not turn the hypothesis test into a Chapter 8 problem.","Tutorial 9 Q10 deliberately asks you to compare the 1% two-tail test with a 99% confidence interval."],"visual":"ciBridge","say":"“For a two-tail Z test, the same-level confidence interval tells the same decision story: null value outside means reject; null value inside means do not reject.”","check":{"q":"A 95% CI for μ is (48,52) and H0:μ=50 in a two-tail α=.05 test. What should the test do?","options":["Do not reject H0","Reject H0","Accept H0"],"answer":"Do not reject H0","why":"The hypothesised value 50 lies inside the 95% interval."},"worked":{"title":"Paint-can cross-check","steps":["The 99% confidence interval is approximately 3.7009 to 3.7591 kg.","The null value μ0=3.75 kg lies inside the interval.","Therefore the equivalent two-tail α=.01 test does not reject H0.","This agrees with Z≈−1.768 being inside ±2.576."],"answer":"The CI and critical-value test agree: do not reject H0.","check":"Same α/confidence pairing: 1−α=.99."},"try":{"type":"choice","q":"A same-level two-tail CI excludes μ0. What is the matching test decision?","options":["Reject H0","Do not reject H0","The two methods must disagree"],"answer":"Reject H0","solution":"Exclusion of μ0 corresponds to the test statistic falling in a rejection tail."},"exit":"Move on when you can predict the test decision just by locating μ0 relative to the same-level two-tail interval.","practiceId":"C9-Q11","sources":["Official Chapter 9 deck: hypothesis-test / confidence-interval connection","SDS Tutorial 9 Q10(c)–(d)"]},{"id":"9.7","title":"Mean Test — σ Unknown: Student t","skills":["C9.26","C9.27","C9.28","C9.29","C9.30"],"objective":"Switch correctly from Z to Student t when σ is unknown, use s and df=n−1, check the source assumptions, and choose the correct t tail/Excel function.","explain":["If the population standard deviation σ is unknown and sample standard deviation s is supplied, the Chapter 9 mean-test route uses Student t.","T=(X̄−μ0)/(s/√n) and df=n−1. The t distribution accounts for uncertainty from estimating σ with s.","The source states the normal-population assumption and discusses checking normality; it also notes t can be used when the sample is not very small and the population is not very skewed.","For two tails the deck uses T.DIST.2T(ABS(tcalc),df); for critical values it shows T.INV with the appropriate cumulative probability."],"visual":"tRoute","say":"“Mean plus unknown population sigma means Student t. I use sample s, divide by square root n, and use degrees of freedom n minus one.”","check":{"q":"n=25 and σ is unknown. What df is used?","options":["24","25","26"],"answer":"24","why":"df=n−1."},"worked":{"title":"Tutorial 9 textbook-cost example","steps":["H0: μ=1500; H1: μ>1500; α=.10.","X̄=1577, s=216, n=25, so df=24.","SE=216/5=43.2.","T=(1577−1500)/43.2≈1.7824.","Upper-tail critical t at α=.10 and df=24 is about 1.318.","1.7824>1.318, so reject H0. The one-tail p-value is about .0437."],"answer":"There is evidence at α=.10 that the population mean textbook cost exceeds R1500.","check":"Unknown σ is why s and t appear."},"try":{"type":"numeric","q":"Battery example: X̄≈473.4615, s≈210.7663, n=13, μ0=500. What is Tcalc?","answer":-0.45399,"tolerance":0.004,"solution":"T=(473.4615−500)/(210.7663/√13)≈−0.454."},"exit":"Move on when the phrase “σ unknown, s supplied” automatically triggers t, df=n−1 and the correct t-tail workflow.","practiceId":"C9-Q13","sources":["Official Chapter 9 deck: Student-t sections and Excel workflow","SDS Tutorial 9 Q12–14"]},{"id":"9.8","title":"One-Tail Mean Tests","skills":["C9.31","C9.14","C9.15","C9.19","C9.30"],"objective":"Write the SDS188 one-tail hypotheses correctly, put all α in the directed tail, and use the matching Z or t probability.","explain":["The source notes a technical inequality form, then states that SDS188 adopts an approximate one-tail format using equality in H0.","For a lower-tail question: H0: μ=μ0 and H1: μ<μ0. For an upper-tail question: H0: μ=μ0 and H1: μ>μ0.","The tail comes from H1. Do not change direction because Zcalc or Tcalc has an unexpected sign.","After the tail is fixed, select Z if σ is known and t if σ is unknown."],"visual":"oneTail","say":"“SDS188 keeps equality in H0. The inequality belongs in H1, and that inequality chooses the tail.”","check":{"q":"“Evidence that mean life is less than 500 hours” gives which H1?","options":["H1: μ<500","H1: μ>500","H1: μ≠500"],"answer":"H1: μ<500","why":"“Less than” is a lower-tail alternative."},"worked":{"title":"ATM upper-tail example","steps":["Question asks whether mean withdrawal is more than R500.","Write H0: μ=500; H1: μ>500.","σ=120 is known, so use Z.","Z=2.5.","At α=.05, the upper critical Z is about 1.645.","2.5 is in the upper rejection tail."],"answer":"Reject H0; there is evidence the mean withdrawal is above R500.","check":"The same data would be handled differently only if H1 had a different direction."},"try":{"type":"choice","q":"A lower-tail test produces Z=−1.38. Which p-value is used?","options":["Φ(−1.38)","2Φ(−1.38)","1−Φ(−1.38)"],"answer":"Φ(−1.38)","solution":"Lower-tail means the cumulative-left probability directly."},"exit":"Move on when you can translate “less than / more than” into H1 and never double a one-tail p-value.","practiceId":"C9-Q12","sources":["Official Chapter 9 deck: one-tail tests and SDS188 H0 convention","SDS Tutorial 9 Q9, Q11–13"]},{"id":"9.9","title":"One-Proportion Z Tests","skills":["C9.32","C9.33","C9.34","C9.35","C9.36"],"objective":"Recognise a binary proportion claim, compute p, check expected counts under H0, calculate Z and make the test decision.","explain":["A one-proportion test is for categorical data with two outcomes, such as defective/not defective or prefer R100/not.","Calculate the sample proportion p=x/n. Under H0, the standard error uses the null population proportion π0 — not the observed p.","Before the normal approximation, the deck requires nπ0≥5 and n(1−π0)≥5.","Then calculate Z=(p−π0)/√[π0(1−π0)/n] and use the alternative hypothesis to choose the critical region or p-value."],"visual":"proportion","say":"“For a proportion test I calculate p equals x over n, check both expected counts using pi-zero, then standardise p using the null standard error.”","check":{"q":"For n=400 and H0:π=.20, what are the two expected-count checks?","options":["80 and 320","88 and 312","20 and 80"],"answer":"80 and 320","why":"Use nπ0 and n(1−π0), not the observed success count for the null approximation check."},"worked":{"title":"Tutorial 9 R100 survey","steps":["x=593, n=1040, so p=593/1040≈.57019.","H0: π=.50; H1: π>.50.","Expected counts: 520 and 520, both ≥5.","SE under H0=√(.5·.5/1040).","Z≈4.527.","The statistic is far into the upper rejection tail; the p-value is extremely small."],"answer":"Reject H0; the sample provides evidence that more than half prefer R100.","check":"The standard error uses π0=.50."},"try":{"type":"numeric","q":"Tutorial 9 Q17: x=88, n=400. What is p?","answer":0.22,"tolerance":0.0001,"solution":"p=88/400=.22."},"exit":"Move on when you can identify binary data, calculate p, check both null expected counts and use π0 in the test standard error.","practiceId":"C9-Q17","sources":["Official Chapter 9 deck: hypothesis tests for proportions","SDS Tutorial 9 Q17–18"]},{"id":"9.10","title":"Power, Planning & Statistical Responsibility","skills":["C9.37","C9.38","C9.39","C9.40"],"objective":"Calculate β/power and understand why statistically significant does not automatically mean practically important or ethically well-designed.","explain":["Power is 1−β, the probability of rejecting H0 when H0 is false. To calculate it, first find the critical sample-mean boundary using the H0 distribution; then evaluate the non-rejection probability under the stated true mean.","The deck states that power increases as the true parameter moves farther from the null, as α increases, and for a correctly directed one-tail test compared with a two-tail test.","Statistical significance and practical importance are not the same. Very large samples can make tiny differences statistically significant; small samples can fail to detect practically important differences.","Planning questions include the study goal, hypotheses, tail, random sampling, data type, α, sample size/power, test procedure and interpretation. Ethical reporting means not selectively reporting only significant findings."],"visual":"power","say":"“Power is one minus beta. I find the rejection boundary under H0, then evaluate beta under the true alternative. Statistical significance still has to be judged for practical importance and reported responsibly.”","check":{"q":"Which statement is correct?","options":["Power=1−β","Power=1−α","Power=α+β"],"answer":"Power=1−β","why":"Power is the probability of rejecting a false H0."},"worked":{"title":"Tutorial 9 Q21, α=.05 and true μ=197","steps":["H0 boundary is based on μ0=200, σ=5.71, n=16.","SE=5.71/4=1.4275.","Lower-tail α=.05 critical Z≈−1.645, so critical X̄≈197.652.","If the true mean is 197, β=P(X̄≥197.652 | μ=197)≈.3239.","Power=1−β≈.6761."],"answer":"β≈.3239 and power≈.6761.","check":"If the true mean moves farther down to 194, power should increase sharply."},"try":{"type":"numeric","q":"Same test, α=.05, but true μ=194. Enter the power.","answer":0.9947407156,"tolerance":0.003,"solution":"Using the same critical boundary 197.652, β≈.00526, so power≈.99474."},"exit":"Move on when you can calculate the critical boundary → β under μtrue → power, and explain why significance alone is not enough.","practiceId":"C9-Q20","sources":["Official Chapter 9 deck: planning, ethics, practical significance and power","SDS Tutorial 9 Q21–22"]}];
  const CH9_LEARN_KEY='SDS188_CH9_LEARN_FORMATIVE_V1';
  function ch9LearnState(){let x={active:'9.1',visited:{},checks:{},tries:{}};try{x={...x,...JSON.parse(localStorage.getItem(CH9_LEARN_KEY)||'{}')}}catch{}return x}
  function saveCh9LearnState(x){try{localStorage.setItem(CH9_LEARN_KEY,JSON.stringify(x))}catch{}}
  function ch9LessonById(id){return CH9_LESSONS.find(x=>x.id===id)}
  function ch9LessonReady(id){const s=ch9LearnState();return s.checks[id]===true&&s.tries[id]===true}
  function ch9LessonPct(){return Math.round(100*CH9_LESSONS.filter(x=>ch9LessonReady(x.id)).length/CH9_LESSONS.length)}
  function renderCh9Visual(l){
    if(l.visual==='foundations')return`<div class="ch9-route"><div class="node">H0 · population parameter<br><small>status quo + equality</small></div><div class="arrow">→</div><div class="node">Sample evidence<br><small>assume H0 first</small></div><div class="arrow">→</div><div class="node">Reject / do not reject H0</div></div>`;
    if(l.visual==='errorMatrix')return`<table class="ch9-matrix"><thead><tr><th>Truth</th><th>Do not reject H0</th><th>Reject H0</th></tr></thead><tbody><tr><th>H0 true</th><td class="ch9-good">Correct</td><td class="ch9-risk">Type I · α</td></tr><tr><th>H0 false</th><td class="ch9-risk">Type II · β</td><td class="ch9-good">Correct · power 1−β</td></tr></tbody></table>`;
    if(l.visual==='tails')return`<div class="ch9-tail-controls"><button type="button" class="active" data-ch9-tail="two">H1: ≠ · TWO</button><button type="button" data-ch9-tail="lower">H1: &lt; · LOWER</button><button type="button" data-ch9-tail="upper">H1: &gt; · UPPER</button></div><div id="ch9-tail-demo" class="ch9-tail-demo two"><span class="leftshade"></span><span class="rightshade"></span></div><div class="ch9-tail-labels"><span>left rejection tail</span><span>non-rejection region</span><span>right rejection tail</span></div>`;
    if(l.visual==='zRoute')return`<div class="ch9-route"><div class="node">Testing μ</div><div class="arrow">→</div><div class="node">σ KNOWN?</div><div class="arrow">→</div><div class="node">YES → Z<br><small>Z=(X̄−μ0)/(σ/√n)</small></div></div>`;
    if(l.visual==='pvalue')return`<div class="ch9-grid2"><div class="ch9-mini"><strong>Meaning</strong><p>Extremeness probability calculated <em>assuming H0 is true</em>.</p></div><div class="ch9-mini"><strong>Decision</strong><p><code>p &lt; α → reject H0</code><br><code>p ≥ α → do not reject H0</code></p></div></div><div class="ch9-formula-strip"><code>two-tail Z: 2[1−Φ(|Z|)]</code><code>Excel: (1−NORM.S.DIST(ABS(Z),TRUE))*2</code></div>`;
    if(l.visual==='ciBridge')return`<div class="ch9-ci-line"><span class="limit l"></span><span class="limit u"></span><span class="mu0" title="μ0"></span><span class="caption">same-level CI · μ0 shown inside → do not reject H0</span></div>`;
    if(l.visual==='tRoute')return`<div class="ch9-route"><div class="node">Testing μ</div><div class="arrow">→</div><div class="node">σ UNKNOWN; s supplied</div><div class="arrow">→</div><div class="node">Student t<br><small>df=n−1</small></div></div>`;
    if(l.visual==='oneTail')return`<div class="ch9-grid2"><div class="ch9-mini"><strong>LOWER</strong><p>H0: μ=μ0<br>H1: μ&lt;μ0<br>all α left</p></div><div class="ch9-mini"><strong>UPPER</strong><p>H0: μ=μ0<br>H1: μ&gt;μ0<br>all α right</p></div></div>`;
    if(l.visual==='proportion')return`<div class="ch9-route"><div class="node">binary outcomes</div><div class="arrow">→</div><div class="node">p=x/n</div><div class="arrow">→</div><div class="node">nπ0≥5 & n(1−π0)≥5</div><div class="arrow">→</div><div class="node">Z proportion test</div></div>`;
    if(l.visual==='power')return`<div class="ch9-power"><div><p class="compact"><strong>Under H0:</strong> find critical X̄ boundary</p><div class="curvebox"><span class="shade"></span></div></div><div><p class="compact"><strong>Under true μ:</strong> non-rejection area = β</p><div class="curvebox"><span class="shade"></span></div></div></div><p class="compact">Then power = 1−β. Greater separation makes β smaller.</p>`;
    return''
  }
  function renderCh9Mini(l){const c=l.check;return`<fieldset class="learn-check"><legend>TINY KNOWLEDGE CHECK · FORMATIVE ONLY</legend><p><strong>${esc(c.q)}</strong></p>${c.options.map(o=>`<label><input type="radio" name="c9c-${esc(l.id)}" value="${esc(o)}"> ${esc(o)}</label>`).join('')}<button class="secondary" type="button" data-ch9-check="${esc(l.id)}">CHECK</button><div class="learn-feedback" id="c9c-feedback-${esc(l.id)}" aria-live="polite"></div></fieldset>`}
  function renderCh9Try(l){const x=l.try,control=x.type==='numeric'?`<input class="learn-numeric" id="c9t-input-${esc(l.id)}" type="number" step="any" inputmode="decimal">`:x.options.map(o=>`<label><input type="radio" name="c9t-${esc(l.id)}" value="${esc(o)}"> ${esc(o)}</label>`).join('');return`<div class="lesson-block lesson-try"><h3>YOUR TURN · FORMATIVE ONLY</h3><p><strong>${esc(x.q)}</strong></p>${x.type==='choice'?`<fieldset class="learn-check" style="margin:.6rem 0">${control}</fieldset>`:control}<div class="question-actions"><button class="primary" type="button" data-ch9-try="${esc(l.id)}">CHECK MY ANSWER</button><button class="secondary" type="button" data-ch9-reveal="${esc(l.id)}">REVEAL WORKED SOLUTION</button></div><div class="learn-feedback" id="c9t-feedback-${esc(l.id)}"></div><div class="notice" id="c9t-solution-${esc(l.id)}" hidden><strong>Worked solution:</strong> ${esc(x.solution)}</div></div>`}
  function renderCh9Roadmap(active){const pct=ch9LessonPct();return`<div class="ch9-source-banner"><strong>CHAPTER 9 · SOURCE_READY</strong><br>The supplied <em>SDS chapter9_2023.pdf</em> was confirmed as the official deck used in 2026. Tutorial 9 is the official practice spine. Q15–16 and Q19–20 are retained as Chapter 8 work and do not count toward Chapter 9 mastery.<div class="learn-progress-strip"><span>Formative lesson readiness: <strong>${pct}%</strong></span><div class="bar"><div class="fill" style="width:${pct}%"></div></div><span>${CH9_LESSONS.filter(x=>ch9LessonReady(x.id)).length}/${CH9_LESSONS.length} checks + your-turns passed</span></div></div><div class="learn-roadmap">${CH9_LESSONS.map(x=>`<button type="button" data-open-ch9-lesson="${x.id}" aria-current="${x.id===active?'step':'false'}"><span class="lesson-code">${x.id}</span><span class="lesson-name">${esc(x.title)}</span><span class="lesson-state ${ch9LessonReady(x.id)?'passed':''}">${ch9LessonReady(x.id)?'FORMATIVE READY':'OPEN LESSON'}</span></button>`).join('')}</div>`}
