  if(QUESTIONS['P-EXCEL-WORKFLOW']){QUESTIONS['P-EXCEL-WORKFLOW'].excelFamily='EXCEL_WORKFLOW_RECONSTRUCTION';QUESTIONS['P-EXCEL-WORKFLOW'].excelExecutionMode='RECONSTRUCTION';QUESTIONS['P-EXCEL-WORKFLOW'].assessesSkillIds=['C6.23'];QUESTIONS['P-EXCEL-WORKFLOW'].designatedEvidenceTarget='C6.23'}

  const SPECIAL_SEMANTICS={
    'C6.01':{fact:'A count such as number of faults is discrete; a measured waiting time is continuous.',wrong:'Every numeric variable is continuous.',a1:'A machine records the number of failures in a shift. Classify the variable.',a1Answer:'Discrete',a1Wrong:'Continuous',a2:'A clinic records waiting time to the nearest second. Classify the underlying variable.',a2Answer:'Continuous',a2Wrong:'Discrete',transfer:'A sensor reports temperature on a continuum while a log records call counts. Which pairing is correct?',transferAnswer:'Temperature continuous; call count discrete',transferWrong:'Temperature discrete; call count continuous',family:'recognition'},
    'C6.07':{fact:'Standardise a normal observation with z=(x-mu)/sigma.',wrong:'Use z=(x-mu)/sigma squared.',a1:'For x=14, mu=10 and sigma=2, calculate z.',a1Answer:'2',a1Wrong:'4',a2:'For x=42, mu=50 and sigma=4, calculate z.',a2Answer:'-2',a2Wrong:'2',transfer:'A battery life of 118 minutes comes from a process with mean 100 and SD 6. What is its standard score?',transferAnswer:'3',transferWrong:'18',family:'calculation'},
    'C6.23':{fact:'For ordered position j in a sample of size n, the plotting position is j/(n+1).',wrong:'The plotting position is always j/n.',a1:'For j=3 and n=15, calculate the plotting position.',a1Answer:'0.1875',a1Wrong:'0.20',a2:'For j=8 and n=19, calculate the plotting position.',a2Answer:'0.40',a2Wrong:'0.4211',transfer:'Twenty-four ordered lifetimes are listed. What plotting probability belongs to rank 5?',transferAnswer:'0.20',transferWrong:'0.2083',family:'excel'},
    'C6.25':{fact:'Construct a normal probability plot with theoretical normal z-values on x and ordered observations on y; approximate linearity supports normality.',wrong:'Plot row number against unsorted observations and treat any curve as normal.',a1:'Which axes implement the supplied normal-probability-plot workflow?',a1Answer:'Normal z on x; ordered X on y',a1Wrong:'Order j on x; unsorted X on y',a2:'A normal probability plot is close to a straight line with no systematic curvature. What conclusion is supported?',a2Answer:'Approximate normality is supported',a2Wrong:'Exact normality is proved',transfer:'A quality-control probability plot bends strongly in both tails. Which reading is defensible?',transferAnswer:'The plot gives evidence against a normal model',transferWrong:'The bend proves the data are normal',family:'interpretation'},
    'C7.04':{fact:'Exact enumeration lists every possible fixed-size sample under the stated replacement and order convention.',wrong:'One convenient sample is enough for an exact enumeration.',a1:'From population {1,2,3}, list all unordered samples of size 2 without replacement.',a1Answer:'{1,2}; {1,3}; {2,3}',a1Wrong:'{1,2}; {2,3}',a2:'From population {2,4,6,8}, how many unordered samples of size 2 without replacement must be enumerated?',a2Answer:'6',a2Wrong:'4',transfer:'A tiny population is {A,B,C,D}. Which list is the complete set of unordered pairs?',transferAnswer:'AB, AC, AD, BC, BD, CD',transferWrong:'AB, AC, AD, BC',family:'enumeration'},
    'C7.05':{fact:'An exact sampling distribution pairs each possible statistic value with its probability across all enumerated samples.',wrong:'It is a frequency table of raw values in one realised sample.',a1:'Samples {1,2}, {1,3}, {2,3} have means 1.5, 2, 2.5. What exact distribution is obtained?',a1Answer:'1.5, 2 and 2.5 each with probability 1/3',a1Wrong:'1, 2 and 3 each with probability 1/3',a2:'Six equally likely samples produce means 2,2,3,3,3,4. What is P(Xbar=3)?',a2Answer:'1/2',a2Wrong:'1/3',transfer:'A complete enumeration yields statistic values 4,5,5,6. Which probability mass belongs at 5?',transferAnswer:'0.5',transferWrong:'0.25',family:'distribution'},
    'C7.08':{fact:'For a sample mean with known population SD, standard error is sigma/sqrt(n).',wrong:'The standard error is sigma/n.',a1:'Population sigma is 12 and n=36. Calculate SE(Xbar).',a1Answer:'2',a1Wrong:'0.3333',a2:'Population sigma is 15 and n=25. Calculate SE(Xbar).',a2Answer:'3',a2Wrong:'0.6',transfer:'A process SD is 18 and an average uses 81 observations. What spread belongs to the average?',transferAnswer:'2',transferWrong:'18',family:'calculation'},
    'C7.27':{fact:'Known population sigma uses the Z lane; unknown sigma with sample s uses the Student-t lane.',wrong:'Sample s is used in the Z lane without changing model.',a1:'A sample mean problem supplies population sigma=8. Select the route.',a1Answer:'Z with sigma/sqrt(n)',a1Wrong:'t with s/sqrt(n)',a2:'A sample mean problem says sigma unknown and supplies s=8. Select the route.',a2Answer:'Student t with s/sqrt(n)',a2Wrong:'Z with sigma=8',transfer:'A laboratory reports only sample SD for a mean based on 20 readings. Which branch applies?',transferAnswer:'Unknown-sigma Student t',transferWrong:'Known-sigma Z',family:'selection'},
    'C7.28':{fact:'When population sigma is unknown, use the sample standard deviation s in s/sqrt(n).',wrong:'Replace unknown sigma with the sample mean.',a1:'Sigma is unknown, s=10 and n=25. What estimated standard error is used?',a1Answer:'2',a1Wrong:'0.4',a2:'Sigma is unknown, s=18 and n=36. What denominator spread is used?',a2Answer:'3',a2Wrong:'0.5',transfer:'A new material test has n=16 and sample SD 12, with no population SD. Which SE enters T?',transferAnswer:'3',transferWrong:'12',family:'calculation'},
    'C7.29':{fact:'With sigma unknown, the standardised sample mean follows a Student-t model with n-1 degrees of freedom.',wrong:'It remains standard normal with no degrees of freedom.',a1:'Which model applies to a normal-population mean when sigma is unknown and s is used?',a1Answer:'Student t',a1Wrong:'Standard normal Z',a2:'A statistic uses (Xbar-mu)/(s/sqrt(n)). Name its sampling model.',a2Answer:'Student t with df=n-1',a2Wrong:'Normal with variance s',transfer:'An analyst estimates mean uncertainty from 14 observations using their sample SD. Which reference distribution is required?',transferAnswer:'t with 13 df',transferWrong:'Z with 14 df',family:'selection'},
    'C7.30':{fact:'Calculate T=(Xbar-mu)/(s/sqrt(n)).',wrong:'Calculate T=(Xbar-mu)/(s*n).',a1:'Xbar=54, mu=50, s=10 and n=25. Calculate T.',a1Answer:'2',a1Wrong:'0.016',a2:'Xbar=97, mu=100, s=12 and n=16. Calculate T.',a2Answer:'-1',a2Wrong:'1',transfer:'A new process has sample mean 33, benchmark 30, sample SD 6 and n=36. Find the t statistic.',transferAnswer:'3',transferWrong:'0.5',family:'calculation'},
    'C7.31':{fact:'For a one-sample Student-t mean statistic, df=n-1.',wrong:'For this lane, df=n.',a1:'A t calculation uses n=20. Determine df.',a1Answer:'19',a1Wrong:'20',a2:'A t calculation uses n=8. Determine df.',a2Answer:'7',a2Wrong:'8',transfer:'Twenty-four independent readings form one sample mean with sigma unknown. What df is used?',transferAnswer:'23',transferWrong:'24',family:'calculation'},
    'C7.32':{fact:'The current source cumulative-left Excel route is =T.DIST(tcalc,df,TRUE).',wrong:'Use =NORM.S.DIST(tcalc,TRUE) for the unknown-sigma t lane.',a1:'Reconstruct the cumulative-left Excel formula for tcalc=1.5 and df=19.',a1Answer:'=T.DIST(1.5,19,TRUE)',a1Wrong:'=T.DIST(1.5,19,FALSE)',a2:'Which formula returns P(T<2.1) with 11 df?',a2Answer:'=T.DIST(2.1,11,TRUE)',a2Wrong:'=NORM.S.DIST(2.1,TRUE)',transfer:'A worksheet has tcalc in B4 and df in B5. Enter the cumulative-left Student-t formula.',transferAnswer:'=T.DIST(B4,B5,TRUE)',transferWrong:'=T.INV(B4,B5)',family:'excel'},
    'C7.33':{fact:'Use Z for a sample mean with known population sigma and t for unknown sigma replaced by sample s.',wrong:'Choose Z or t according to whether the sample mean is positive.',a1:'Population sigma is known and n=12. Select the reference distribution.',a1Answer:'Z',a1Wrong:'t',a2:'Population sigma is unknown, s is supplied and n=12. Select the reference distribution.',a2Answer:'t with 11 df',a2Wrong:'Z',transfer:'Two reports have the same n: Report A gives population SD; Report B only gives sample SD. Match the methods.',transferAnswer:'A uses Z; B uses t',transferWrong:'Both use Z',family:'selection'},
    'C7.44':{fact:'The random object for two independent sample means is Xbar1-Xbar2.',wrong:'The object is one raw observation from each group.',a1:'Two independent classes are compared by their average marks. Identify the random object.',a1Answer:'Xbar1-Xbar2',a1Wrong:'X1-X2',a2:'A study compares mean waiting times for two independent clinics. Which statistic varies?',a2Answer:'Difference of sample means',a2Wrong:'Difference of population means',transfer:'Independent teams each produce an average. Which sampled quantity is modelled?',transferAnswer:'The difference between the two averages',transferWrong:'A single individual difference',family:'recognition'},
    'C7.45':{fact:'The centre of Xbar1-Xbar2 is mu1-mu2.',wrong:'Its centre is mu1+mu2.',a1:'If mu1=80 and mu2=74, state the centre of Xbar1-Xbar2.',a1Answer:'6',a1Wrong:'154',a2:'If mu1=12 and mu2=20, state the centre in order 1-2.',a2Answer:'-8',a2Wrong:'8',transfer:'Group A is designated 1 with mean 30; group B is 2 with mean 27. What centre follows the stated order?',transferAnswer:'3',transferWrong:'-3',family:'calculation'},
    'C7.46':{fact:'For independent known-sigma means, SE=sqrt(sigma1^2/n1+sigma2^2/n2).',wrong:'Add sigma1/n1 and sigma2/n2 without variances or square root.',a1:'sigma1=6,n1=9,sigma2=8,n2=16. Calculate the two-mean SE.',a1Answer:'2.8284',a1Wrong:'1.1667',a2:'sigma1=10,n1=25,sigma2=12,n2=36. Calculate the SE.',a2Answer:'2.8284',a2Wrong:'4',transfer:'Two independent averages each have component SE 3. What is the SE of their difference?',transferAnswer:'4.2426',transferWrong:'6',family:'calculation'},
    'C7.47':{fact:'Translate group 1 greater than group 2 by c as Xbar1-Xbar2>c.',wrong:'Reverse the group order after reading greater than.',a1:'Group 1 exceeds group 2 by more than 5. Write the event.',a1Answer:'Xbar1-Xbar2>5',a1Wrong:'Xbar2-Xbar1>5',a2:'Group 1 is at least 2 below group 2. Which event matches?',a2Answer:'Xbar1-Xbar2<=-2',a2Wrong:'Xbar1-Xbar2>=2',transfer:'Brand A average lasts over 4 hours longer than Brand B. Use order A-B.',transferAnswer:'XbarA-XbarB>4',transferWrong:'XbarB-XbarA>4',family:'representation'},
    'C7.48':{fact:'Standardise the difference using centre mu1-mu2 and the independent-means SE, then calculate the requested tail.',wrong:'Standardise using centre zero regardless of population means.',a1:'A difference has centre 5 and SE 2. Find z for boundary 9.',a1Answer:'2',a1Wrong:'4.5',a2:'A difference has centre -3 and SE 4. Find z for boundary 1.',a2Answer:'1',a2Wrong:'-0.5',transfer:'The A-B mean difference is centred at 12 with SE 3. What standardised boundary corresponds to 18?',transferAnswer:'2',transferWrong:'10',family:'calculation'},
    'C7.49':{fact:'Preserve the declared group order in event, centre and standardisation numerator.',wrong:'Swap order when the numerical centre is negative.',a1:'The object is Xbar1-Xbar2. Which centre preserves that order?',a1Answer:'mu1-mu2',a1Wrong:'mu2-mu1',a2:'The object is XbarB-XbarA. Which numerator preserves order?',a2Answer:'(XbarB-XbarA)-(muB-muA)',a2Wrong:'(XbarA-XbarB)-(muB-muA)',transfer:'A report defines treatment-control. Which event says treatment is higher?',transferAnswer:'XbarT-XbarC>0',transferWrong:'XbarC-XbarT>0',family:'representation'},
    'C7.50':{fact:'Interpret the probability as a statement about the difference between two sample means in the declared order.',wrong:'Interpret it as the probability that fixed population means change.',a1:'What does P(Xbar1-Xbar2>5)=0.20 describe?',a1Answer:'The chance that the sampled mean difference 1-2 exceeds 5',a1Wrong:'A 20% chance that mu1-mu2 changes',a2:'A probability is calculated for XbarA-XbarB<0. Which wording is valid?',a2Answer:'The chance the sampled A mean is below the sampled B mean',a2Wrong:'The chance every A observation is below every B observation',transfer:'P(XbarNew-XbarOld>2)=0.08. Interpret the random quantity.',transferAnswer:'A new pair of samples has an 8% chance of a mean difference above 2',transferWrong:'There is an 8% chance the fixed population difference changes',family:'interpretation'},
    'C7.51':{fact:'The sourced two-mean model requires independent samples and the stated population/model conditions.',wrong:'Paired observations may be treated as independent without checking.',a1:'The same people are measured before and after. Does the independent two-mean route apply?',a1Answer:'No; the samples are paired',a1Wrong:'Yes; there are two columns',a2:'Two groups are sampled independently from sourced normal populations with known sigmas. Is the route supported?',a2Answer:'Yes',a2Wrong:'No because means can never be normal',transfer:'Separate random samples are drawn from two plants. What condition must remain explicit?',transferAnswer:'Independence between the two samples',transferWrong:'Equal sample sizes are mandatory',family:'selection'}
  };
  const S=(fact,wrong,a1,a1Answer,a1Wrong,a2,a2Answer,a2Wrong,transfer,transferAnswer,transferWrong,family)=>({fact,wrong,a1,a1Answer,a1Wrong,a2,a2Answer,a2Wrong,transfer,transferAnswer,transferWrong,family});
  Object.assign(SPECIAL_SEMANTICS,{
    'C6.02':S('For a continuous density, interval probability is area under the density curve.','The density height at one point is the probability at that exact point.','A density is shaded from 2 to 5. What represents P(2<X<5)?','The area under the density between 2 and 5','The height of the density at 5','A valid density has total area 1. What is P(X in its full support)?','1','The maximum density height','A waiting-time density is shaded to the left of 4 minutes. What does the shading represent?','P(X<4) as area under the curve','P(X=4) as the curve height','probability'),
    'C6.03':S('Normal notation X~N(mu,sigma^2) records the mean and variance.','The second normal parameter is the standard deviation without squaring.','A normal variable has mean 5 and variance 9. Write its model.','X~N(5,9)','X~N(5,3)','X~N(20,16). What are mu and sigma?','mu=20; sigma=4','mu=20; sigma=16','A process has mean 100 and SD 6. Which notation is correct?','X~N(100,36)','X~N(100,6)','notation'),
    'C6.04':S('Changing mu shifts the normal curve horizontally without changing its spread.','Changing mu widens the curve.','Model A is N(10,4) and B is N(14,4). How does B differ?','Shifted 4 units right with the same spread','Twice as wide','If mu decreases from 20 to 12 while sigma stays 3, what changes?','The centre shifts 8 units left','The variance becomes 8','Two machines have equal SD but means 50 and 55. How do their curves compare?','Same shape; the second is shifted right','Same centre; the second is wider','normal'),
    'C6.05':S('Increasing sigma increases normal spread while mu stays at the centre.','Increasing sigma shifts the centre.','Compare N(0,4) with N(0,16). Which is more spread out?','N(0,16)','N(0,4)','Variance falls from 25 to 9 at the same mean. What happens?','The curve becomes narrower','The curve shifts left','Two processes share mean 40 but SDs 2 and 7. Which has more variable outcomes?','The process with SD 7','The process with SD 2','normal'),
    'C6.06':S('The standard normal variable is Z~N(0,1).','The standard normal has arbitrary mean and variance.','Which distribution is the standard normal?','N(0,1)','N(1,0)','A score has already been converted to z. What are the reference centre and SD?','0 and 1','1 and 0','A table is labelled standard normal. Which random variable belongs on its axis?','Z with mean 0 and SD 1','X with its original units','normal'),
    'C6.08':S('Below a boundary translates to a left-tail event and cumulative-left probability.','Below requires a right-tail complement.','Translate “less than 12” into a region.','Left of 12','Right of 12','Which probability matches values below c?','P(X<c)','P(X>c)','A service target asks for waits under 6 minutes. Which region is required?','P(X<6), the left tail','P(X>6), the right tail','region'),
    'C6.09':S('Above a boundary translates to a right-tail event, usually 1-CDF.','Above is read directly as cumulative-left area.','Translate “more than 70” into a region.','Right of 70','Left of 70','If Phi(z)=0.84, what is the probability above z?','0.16','0.84','A battery warranty concerns lifetimes exceeding 500 cycles. Which event applies?','P(X>500)','P(X<500)','region'),
    'C6.10':S('A between probability is CDF(upper)-CDF(lower).','A between probability adds the two CDF values.','If F(8)=0.90 and F(3)=0.25, find P(3<X<8).','0.65','1.15','Which expression gives P(a<X<b)?','F(b)-F(a)','F(a)-F(b)','A temperature must lie from 18 to 24. Which calculation is correct?','F(24)-F(18)','1-F(24)+F(18)','region'),
    'C6.11':S('For a continuous variable, P(X<c)=P(X<=c) because P(X=c)=0.','Strict and inclusive inequalities always differ for continuous variables.','For continuous X, compare P(X<4) and P(X<=4).','They are equal','The inclusive probability is larger','Why can a normal calculation ignore < versus <= at one boundary?','An exact point has probability zero','The normal curve has height zero there','A continuous waiting time is measured. Does P(X>6) equal P(X>=6)?','Yes','No','probability'),
    'C6.12':S('An inverse normal problem gives probability and asks for an unknown boundary.','An inverse problem gives the boundary and asks for probability.','The top 5% begins at unknown x. What kind of problem is this?','Inverse normal','Forward normal','P(X<14) is requested with all parameters known. What kind is it?','Forward probability','Inverse boundary','A percentile rank is supplied and the original-unit score is unknown. Select the route.','Inverse normal','Normal density height','inverse'),
    'C6.13':S('A right-tail proportion r converts to cumulative-left area 1-r before an inverse lookup.','Use r itself as the cumulative-left area.','The top 10% starts at x. Which left area enters the inverse?','0.90','0.10','The largest 2% exceed x. Which cumulative probability belongs to x?','0.98','0.02','A cutoff leaves 15% above it. What NORM.INV probability is used?','0.85','0.15','inverse'),
    'C6.14':S('Find an unknown z boundary by applying the inverse standard-normal function to cumulative-left area.','Use the standard-normal CDF on the probability itself.','Which Excel formula returns z for cumulative area 0.975?','=NORM.S.INV(0.975)','=NORM.S.DIST(0.975,TRUE)','The cumulative-left area is 0.25. What is the sign of z?','Negative','Positive','A lower-tail probability 0.90 is given. Which object is returned by the inverse step?','The z boundary','The original mu','inverse'),
    'C6.15':S('Back-transform a z boundary with x=mu+z*sigma.','Back-transform with x=(z-mu)/sigma.','mu=50, sigma=4 and z=1.5. Find x.','56','12.875','mu=20, sigma=5 and z=-2. Find x.','10','30','A standardized cutoff is 0.5 for a process with mean 100 and SD 8. What is the original cutoff?','104','12.5','inverse'),
    'C6.16':S('For a central proportion, split the remaining probability equally across two tails and find symmetric z limits.','Put all remaining probability in one tail.','For a central 80%, what probability is in each tail?','0.10','0.20','Which cumulative areas define the central 90% limits?','0.05 and 0.95','0.10 and 0.90','A central 98% interval is required. Which lower cumulative area is used?','0.01','0.02','inverse'),
    'C6.17':S('Relative standing is compared with z-scores, not raw scores from different scales.','The larger raw score always has higher relative standing.','A=80 from mean 70 SD 5; B=90 from mean 75 SD 10. Who stands higher?', 'A: z=2 versus B: z=1.5','B because 90 is larger','Score 55 from mean 50 SD 2 and score 75 from mean 60 SD 10: which is higher relatively?','55-score: z=2.5','75-score: z=1.5','Two applicants have z scores -0.2 and 0.6 on different tests. Who ranks higher?','The applicant with z=0.6','The applicant with the larger raw test maximum','normal'),
    'C6.18':S('For a symmetric unimodal distribution, mean, median and mode are approximately equal.','A large mean-median gap is evidence of symmetry.','Mean=20.1, median=20.0 and mode=20.2. What do these support?','Approximate symmetry','Strong right skew','Mean=35, median=28 and mode=24. Is equality evidence present?','No','Yes','A dataset has nearly coincident mean, median and mode. How should this be used?','As supporting, not conclusive, symmetry evidence','As proof of exact normality','normality'),
    'C6.19':S('Mean greater than median supports right skew; mean less than median supports left skew.','Mean above median implies left skew.','Mean=42 and median=35. Infer skew direction.','Right-skewed','Left-skewed','Mean=18 and median=23. Infer skew direction.','Left-skewed','Right-skewed','A salary distribution has a few large values pulling mean above median. Which skew is expected?','Right skew','Left skew','normality'),
    'C6.20':S('A normal model places about 68%, 95% and 99.7% within 1, 2 and 3 SDs of the mean.','About 95% lies within one SD.','Approximately what percentage lies within mu plus or minus 2 sigma?','95%','68%','A dataset has 68% within one SD and 95% within two. What does this provide?','Support for approximate normality','Proof of exact normality','A normal process has mean 100 SD 5. About 99.7% lies between which values?','85 and 115','95 and 105','normality'),
    'C6.21':S('Skewness near 0 and normal-like kurtosis are supporting evidence, not standalone proof.','Any finite skewness proves normality.','Sample skewness is close to 0. What is a defensible use?','Supporting symmetry evidence','Proof of normality','Skewness is strongly positive. What does this suggest?','Right-tail asymmetry','Exact symmetry','Kurtosis and skewness look normal-like but the plot has severe curvature. What conclusion follows?','Integrate all evidence; do not certify normality from two numbers','Ignore the plot and declare normality','normality'),
    'C6.22':S('Plots should be inspected for symmetry, outliers and systematic departures from the expected shape.','A plot title alone establishes normality.','A histogram has balanced tails and no obvious outliers. What does it provide?','Graphical support for symmetry','Proof of a normal population','A boxplot has a long upper whisker and high outliers. What is suggested?','Right skew or tail departure','Perfect symmetry','A density plot is bimodal. Is a single normal model well supported?','No','Yes','normality'),
    'C6.24':S('Convert plotting probability alpha_j to theoretical normal score z_j with NORM.S.INV(alpha_j).','Use NORM.S.DIST(alpha_j,TRUE) to obtain z_j.','alpha_j=0.25. Which Excel step returns its theoretical z?','=NORM.S.INV(0.25)','=NORM.S.DIST(0.25,TRUE)','What sign should z have when alpha_j<0.5?','Negative','Positive','A plotting position is 0.90. Which value is placed on the theoretical-normal axis?','NORM.S.INV(0.90)','0.90 itself without conversion','excel'),
    'C6.26':S('An integrated normality conclusion combines numerical summaries and graphical evidence and states uncertainty.','One favourable check proves exact normality.','Mean and median are close, skewness is small and the probability plot is nearly linear. What is defensible?','The data support approximate normality','The population is proven exactly normal','The histogram looks bell-shaped but the probability plot curves strongly. What should happen?','Report conflicting evidence and avoid a firm normal conclusion','Use the histogram alone','A formal report has mixed diagnostics. Which wording is sound?','Normality is not adequately supported by the combined evidence','One acceptable statistic overrides all other checks','normality'),
    'C6.27':S('A binomial count may use a normal approximation only after both source conditions are checked.','Every count with n>30 is automatically normal.','X counts successes in 200 independent trials. What approximation may be considered after condition checks?','Normal approximation to binomial','Exponential waiting-time approximation','X is continuous lifetime. Is the binomial-normal route relevant?','No','Yes','A large Bernoulli count is requested. What distribution is exact before approximation?','Binomial','Uniform','binomial'),
    'C6.28':S('Check both n*pi>5 and n*(1-pi)>5.','Checking only n*pi is sufficient.','n=100 and pi=0.08. Do both conditions hold?','Yes: 8 and 92 exceed 5','No because pi is below 0.5','n=20 and pi=0.10. Is normal approximation allowed?','No: n*pi=2','Yes: n is above 5','n=50 and pi=0.90. Which condition is borderline or failing?','n*(1-pi)=5, not greater than 5','n*pi=45','binomial'),
    'C6.29':S('The approximate normal mean for a binomial count is n*pi.','The approximate mean is pi/n.','n=80 and pi=0.25. Find the approximate mean.','20','0.003125','n=40 and pi=0.60. Find the centre.','24','16','A defect count has n=500 and defect probability 0.02. Where is its approximation centred?','10','0.02','binomial'),
    'C6.30':S('The approximate normal SD for a binomial count is sqrt(n*pi*(1-pi)).','The SD is n*pi*(1-pi) without a square root.','n=100 and pi=0.25. Find the approximate SD.','4.3301','18.75','n=200 and pi=0.50. Find the SD.','7.0711','50','A count has variance n*pi*(1-pi)=36. What SD enters z?','6','36','binomial'),
    'C6.31':S('For exact discrete value X=x, continuity correction uses x-0.5<X_a<x+0.5.','Use a single boundary x+0.5 for exact equality.','Continuity-correct X=12.','11.5<X_a<12.5','X_a<12.5','Which continuous interval represents exactly 7 successes?','6.5<X_a<7.5','7<X_a<8','A claim asks for exactly 25 defects. Which corrected region is used?','24.5<X_a<25.5','X_a>24.5','binomial'),
    'C6.32':S('Continuity correction maps <=x to <x+0.5 and >=x to >x-0.5, with analogous strict boundaries.','All inequalities use x+0.5.','Continuity-correct X>=25.','X_a>24.5','X_a>25.5','Continuity-correct X<=10.','X_a<10.5','X_a<9.5','Continuity-correct X>40.','X_a>40.5','X_a>39.5','binomial'),
    'C6.33':S('Standardise the continuity-corrected boundary using the approximate binomial mean and SD.','Standardise the uncorrected integer after applying continuity correction.','Mean=20, SD=4 and event X>=25. Find corrected z boundary.','1.125','1.25','Mean=50, SD=5 and event X<=42. Find corrected z boundary.','-1.5','-1.6','A count has centre 30, SD 3 and event X>35. What z uses the corrected boundary?','1.8333','1.6667','binomial'),
    'C6.34':S('The exact binomial result is a benchmark; the normal approximation should be close only when conditions and correction are sound.','An approximation must equal the exact result digit for digit.','Exact probability is 0.154 and normal approximation is 0.151. How should they be described?','Close, with small approximation error','Identical methods','Conditions fail and the approximation differs sharply. Which result is authoritative?','The exact binomial result','The normal approximation','Two software outputs differ slightly after valid correction. What should be checked?','Magnitude of approximation error and conditions','Discard the exact binomial calculation','binomial'),
    'C6.35':S('A continuous uniform distribution has constant density on a finite interval [a,b].','Uniform density is bell-shaped on the real line.','A waiting time is equally likely per unit over 0 to 10. Which model fits?','Uniform(0,10)','Normal(0,10)','A density is constant between 3 and 7 and zero outside. Identify it.','Uniform(3,7)','Exponential with rate 4','A random angle is equally distributed from 0 to 360 degrees. Which continuous family is natural?','Uniform','Poisson','uniform'),
    'C6.36':S('For Uniform(a,b), a and b are the lower and upper support bounds.','a and b are the mean and variance.','X is uniform from 2 to 8. Identify a and b.','a=2, b=8','a=5, b=6','A density is nonzero only on [-3,5]. What are the bounds?','a=-3, b=5','a=3, b=5','Delivery time is uniform between 10 and 25 minutes. What support should be written?','[10,25]','[0,15]','uniform'),
    'C6.37':S('Uniform density height is 1/(b-a).','Uniform density height is b-a.','For Uniform(2,8), calculate the density height.','1/6','6','For Uniform(-1,3), calculate the height.','1/4','4','A uniform support has width 20. What is its density?','0.05','20','uniform'),
    'C6.38':S('Uniform interval probability is interval width divided by total support width.','Uniform probability equals the interval endpoint sum.','For Uniform(0,10), find P(2<X<5).','0.3','0.7','For Uniform(4,12), find P(6<X<10).','0.5','0.25','A train arrival is uniform over 30 minutes. What is the chance of a 6-minute subinterval?','0.2','5','uniform'),
    'C6.39':S('Solve a uniform complement by subtracting the included interval probability from 1.','Add the excluded interval probability to 1.','For Uniform(0,10), find P(X>7).','0.3','0.7','For Uniform(2,8), find P(X<3 or X>7).','1/3','2/3','A value is uniform on [0,100]. What is P(X not between 20 and 80)?','0.4','0.6','uniform'),
    'C6.40':S('Uniform mean is (a+b)/2, the midpoint of the support.','Uniform mean is b-a.','For Uniform(2,8), calculate the mean.','5','6','For Uniform(-4,10), calculate the mean.','3','7','A uniform delivery window is 20 to 50 minutes. Interpret the mean.','The long-run average is 35 minutes','Every delivery takes 35 minutes','uniform'),
    'C6.41':S('Uniform variance is (b-a)^2/12 and SD is (b-a)/sqrt(12).','Uniform SD is b-a.','For Uniform(0,12), calculate the variance.','12','144','For Uniform(2,8), calculate the SD.','1.7321','3','A support width doubles. What happens to uniform SD?','It doubles','It quadruples','uniform'),
    'C6.42':S('The exponential distribution models continuous waiting time to an event.','Exponential models the count of events in an interval.','Which model fits time until the next call?','Exponential','Poisson','Which model fits number of calls in an hour?','Poisson, not exponential','Exponential','A component lifetime until failure is requested. Which family is appropriate under a constant-rate assumption?','Exponential','Binomial count','exponential'),
    'C6.43':S('Lambda is an event rate per unit time, so its units must match the time variable.','Lambda is the mean waiting time itself.','lambda=12 per hour. What does it mean?','An average rate of 12 events per hour','A mean wait of 12 hours','A rate is 0.5 per minute. Which time unit should enter lambda*t directly?','Minutes','Hours without conversion','Calls arrive at 30 per hour. What is the equivalent rate per minute?','0.5','30','exponential'),
    'C6.44':S('The exponential mean waiting time is 1/lambda.','The mean is lambda.','lambda=4 per hour. Find E(X) in hours.','0.25','4','lambda=0.2 per minute. Find the mean wait.','5 minutes','0.2 minutes','A process averages 10 events per hour. What is the mean interarrival time?','0.1 hour','10 hours','exponential'),
    'C6.45':S('Exponential left-tail probability is P(X<=t)=1-exp(-lambda*t).','The left tail is exp(-lambda*t).','lambda=2 and t=0.5. Which expression gives P(X<=0.5)?','1-exp(-1)','exp(-1)','If exp(-lambda*t)=0.30, what is the left-tail probability?','0.70','0.30','A customer waits no more than 3 minutes. Which exponential form applies?','1-exp(-lambda*3)','exp(-lambda*3)','exponential'),
    'C6.46':S('Exponential right-tail probability is P(X>=t)=exp(-lambda*t).','The right tail is 1-exp(-lambda*t).','lambda=0.5 and t=4. Which expression gives P(X>4)?','exp(-2)','1-exp(-2)','If the left-tail probability is 0.82, what is the right tail?','0.18','0.82','A lifetime exceeds 100 hours. Which form is used?','exp(-lambda*100)','1-exp(-lambda*100)','exponential'),
    'C6.47':S('Exponential between probability is F(b)-F(a); outside is 1-[F(b)-F(a)].','Between probability is F(a)-F(b).','If F(8)=0.90 and F(3)=0.55, find P(3<X<8).','0.35','1.45','If P(2<X<5)=0.40, find P(X<2 or X>5).','0.60','0.40','A wait is outside 4 to 10 minutes. Which expression is correct?','1-[F(10)-F(4)]','F(10)-F(4)','exponential'),
    'C6.48':S('Convert rate and time to the same unit before forming lambda*t.','Multiply an hourly rate by minutes directly.','lambda=12 per hour and t=5 minutes. Find lambda*t.','1','60','lambda=0.5 per minute and t=2 hours. Find lambda*t.','60','1','A rate is 3 per day and time is 8 hours. What common-unit product is used?','1','24','exponential'),
    'C6.49':S('For exponential cumulative probability alpha, the boundary is -ln(1-alpha)/lambda.','Use ln(alpha)*lambda.','lambda=2 and alpha=0.5. Which boundary expression is correct?','-ln(0.5)/2','ln(0.5)*2','What equation is solved when P(X<=x)=0.90?','1-exp(-lambda*x)=0.90','exp(-lambda*x)=0.90 for the left tail','A 95th percentile wait is requested. Which quantity is unknown?','The time boundary x','The event rate when lambda is supplied','exponential'),
    'C6.50':S('Poisson models counts in an interval; exponential models waiting time between events.','Poisson models waiting time and exponential models counts.','Number of arrivals in 10 minutes: choose the object family.','Poisson count','Exponential wait','Minutes until the next arrival: choose the object family.','Exponential wait','Poisson count','A call centre asks both calls per hour and time to next call. Match them.','Poisson for count; exponential for wait','Exponential for count; Poisson for wait','selection')
  });
  Object.assign(SPECIAL_SEMANTICS,{
    'C7.01':S('A population is the full group, a sample is observed from it, a parameter describes the population and a statistic is calculated from the sample.','A sample statistic is a fixed population parameter.','All 5,000 students are the target and 200 are surveyed. Identify population and sample.','5,000 population; 200 sample','200 population; 5,000 sample','The sample mean is 72. Is 72 a parameter or statistic?','Statistic','Parameter','A factory targets all bolts but measures 50 and reports their defect proportion. Classify the reported proportion.','A sample statistic','A population parameter','sampling-foundations'),
    'C7.02':S('A sampling distribution is the distribution of a statistic across all possible fixed-size samples.','It is the raw-data distribution inside one sample.','Repeated samples of n=20 produce many sample means. What distribution do those means form?','The sampling distribution of Xbar','The population distribution of individuals','Which object varies in the sampling distribution of p?','The sample proportion across samples','The fixed population proportion','A simulation redraws samples and records a median each time. What is built?','A sampling distribution of the sample median','A single sample histogram','sampling-foundations'),
    'C7.03':S('Different random samples generally produce different statistic values; this is sample-to-sample variability.','Every random sample has the same mean.','Two random samples have means 48 and 52. What does the difference illustrate?','Sample-to-sample variability','A changed population mean','If n increases, do all sample means become identical?','No','Yes','Repeated polls from one fixed population give slightly different p values. What explains this?','Random sampling variability','The population proportion changing between draws','sampling-foundations'),
    'C7.06':S('E(Xbar)=mu means the sample mean is unbiased over repeated sampling.','Unbiasedness means every sample mean equals mu.','The average of all possible sample means is 40, equal to mu. What property is shown?','Unbiasedness','Zero sampling variability','One sample mean is 43 while mu=40. Does this disprove unbiasedness?','No','Yes','Across repeated samples, the estimator centres at the population value. Name the property.','Unbiasedness','Consistency only','sampling-foundations'),
    'C7.07':S('Standard error is the standard deviation of a statistic across its sampling distribution.','Standard error is the SD of raw observations in one sample.','What spread is described by SD of many possible sample means?','Standard error of Xbar','Population SD of X','A poll reports the sampling variability of p. What measure is this?','Standard error of p','Sample size','A statistic has a narrow sampling distribution. What does that say about its SE?','The SE is small','The population mean is small','sampling-foundations'),
    'C7.09':S('Because SE(Xbar)=sigma/sqrt(n), larger n reduces SE at a square-root rate.','Larger n increases the centre of Xbar.','If n grows from 25 to 100, what happens to SE?','It halves','It quarters','If n is multiplied by 9, how does SE change?','It becomes one third','It becomes one ninth','Two surveys use the same population SD but sample sizes 40 and 160. Which mean is less variable?','The n=160 sample mean','The n=40 sample mean','sampling-foundations'),
    'C7.10':S('X denotes one individual observation, not an average.','X always denotes a sample mean.','A question asks for one randomly selected student mark. What is the random object?','X','Xbar','Which spread belongs to one normal observation with population SD sigma?','sigma','sigma/sqrt(n)','A randomly chosen bottle volume is studied. Which object is modelled?','X for one bottle','Xbar for an average of bottles','object-selection'),
    'C7.11':S('Xbar denotes the average of n sampled observations.','Xbar denotes one raw observation.','A question asks for the average of 36 students. What is the random object?','Xbar','X','Which object uses standard error sigma/sqrt(n)?','Xbar','One observation X','A batch mean from 20 items is recorded. Which symbol belongs to the sampled quantity?','Xbar','mu','object-selection'),
    'C7.12':S('The sampling distribution of Xbar is centred at the population mean mu.','It is centred at sigma/sqrt(n).','Population mean is 80. Where is Xbar centred?','80','The realised sample mean only','If mu changes from 20 to 24, what happens to the Xbar centre?','It changes to 24','It remains 20','A sample-average distribution is shown around 500. What population feature does 500 represent?','mu','sigma','object-selection'),
    'C7.13':S('The spread of Xbar is standard error sigma/sqrt(n), not sigma.','The spread of an average remains sigma.','sigma=10 and n=25. What spread belongs to Xbar?','2','10','Population variance is 64 and n=16. Find the Xbar spread.','2','4','Two random objects are X and Xbar from n=49 with sigma=14. Match their spreads.','X:14; Xbar:2','Both:14','object-selection'),
    'C7.14':S('A probability about Xbar refers to a random sample average, not one person or the fixed population mean.','It is the probability that mu changes.','Interpret P(Xbar>75)=0.10.','10% of repeated samples have an average above 75','10% of individuals exceed 75','What does P(Xbar<20) describe?','The chance a random sample mean is below 20','The chance the fixed mu is below 20','A delivery study calculates a probability for the mean of 30 deliveries. What must the wording mention?','A sample average of 30 deliveries','One delivery only','interpretation'),
    'C7.15':S('For a normal population with known sigma, the sample-mean route uses a normal Z model.','Known sigma requires Student t.','The population is normal, sigma=12 is known and n=9. Select the mean route.','Z with sigma/sqrt(n)','t with sample s','Does a normal population make Xbar normal for a valid n?','Yes','Only when n>30','A quality process is normal with known population variance. Which reference distribution applies to its sample mean?','Normal Z','Exponential','known-sigma-mean'),
    'C7.16':S('For known sigma, Xbar has centre mu, variance sigma^2/n and SE sigma/sqrt(n).','Its variance is sigma^2 and SE is sigma.','mu=50, sigma=10, n=25. State centre and SE.','50 and 2','2 and 50','sigma^2=36 and n=9. What is Var(Xbar)?','4','2','A normal mean model has mu=100, sigma=15 and n=25. Which specification is correct?','Xbar~N(100,9)','Xbar~N(100,15)','known-sigma-mean'),
    'C7.17':S('A left-tail mean probability standardises Xbar and uses Phi(z).','A left-tail uses 1-Phi(z).','mu=50, sigma=10, n=25. Which route gives P(Xbar<54)?','Phi((54-50)/2)','1-Phi((54-50)/2)','After z=-1.2 for a below event, which probability is returned?','Phi(-1.2)','1-Phi(-1.2)','A sample average must be under a limit. Which tail operation follows standardisation?','Cumulative left','Right-tail complement','known-sigma-mean'),
    'C7.18':S('A between mean probability is Phi(z_upper)-Phi(z_lower).','It adds the two cumulative probabilities.','z_lower=-1 and z_upper=1.5. Which expression is correct?','Phi(1.5)-Phi(-1)','Phi(1.5)+Phi(-1)','Which event represents a<Xbar<b?','A between region for the sample mean','Two independent one-sided events added','A sample-average tolerance is 98 to 102. What operation is needed after two z values?','Upper CDF minus lower CDF','One minus both CDFs','known-sigma-mean'),
    'C7.19':S('A right-tail mean probability is 1-Phi(z_boundary).','It is Phi(z_boundary).','After standardisation z=1.4 for Xbar above a boundary, which expression applies?','1-Phi(1.4)','Phi(1.4)','If cumulative-left output is 0.82, find the probability above.','0.18','0.82','A sample mean exceeds a specification limit. Which final Excel-output step is required?','Subtract cumulative-left output from 1','Use cumulative-left output unchanged','known-sigma-mean'),
    'C7.20':S('For an inverse mean boundary, convert the probability to a z boundary and use xbar=mu+z*sigma/sqrt(n).','Use xbar=mu+z*sigma without dividing by sqrt(n).','mu=100, sigma=12, n=36 and z=1. Find the mean boundary.','102','112','The top 5% of sample means starts at xbar. Which left area is used first?','0.95','0.05','A lower 10th-percentile boundary for averages is requested. Which spread enters the back-transform?','sigma/sqrt(n)','sigma','known-sigma-mean'),
    'C7.21':S('Central symmetric limits for sample means are mu plus or minus z* sigma/sqrt(n).','Use mu plus or minus z*sigma for averages.','mu=50, sigma=10, n=25 and z=1.96. Find the 95% sample-mean limits.','46.08 and 53.92','30.4 and 69.6','For a central 90%, which cumulative z areas define the limits?','0.05 and 0.95','0.10 and 0.90','A process asks where the middle 80% of sample averages fall. What structure is used?','mu plus or minus z_0.90 times SE','mu plus or minus 0.80 times sigma','known-sigma-mean'),
    'C7.22':S('Under the CLT, the sampling distribution of Xbar becomes approximately normal for large enough n.','The original population becomes normal.','What object becomes approximately normal under the CLT?','The sampling distribution of Xbar','Each raw observation','A skewed population is sampled with large n. What approximate model concerns the averages?','Normal model for Xbar','Normal model for the original X values','A factory population remains exponential. What can still become approximately normal?','Means of large random samples','Individual lifetimes','clt'),
    'C7.23':S('If the population is normal, Xbar is exactly normal for every valid sample size.','Exact normality requires n>30 even for a normal population.','X is normal and n=4. What is the shape of Xbar?','Exactly normal','Unknown until n=30','A normal population is sampled with n=1. What is the Xbar distribution?','Normal, the same as X','Student t solely because n is small','A source says the population model is normal. Is CLT approximation needed to justify Xbar normality?','No','Yes','clt'),
    'C7.24':S('For a non-normal population, use the source-aligned large-enough-n CLT logic and retain conditions.','Any n makes Xbar normal.','A strongly skewed population is sampled with n=3. Is CLT normality automatically justified?','No','Yes','A non-normal population is sampled with a large independent random sample. What may be justified?','Approximate normality of Xbar','Exact normality of X','A sample size is described only as small with no population shape. What should the learner do?','Do not assert the normal mean model without support','Invoke CLT automatically','clt'),
    'C7.25':S('For a large sample from an exponential population, CLT may approximate the distribution of Xbar as normal.','CLT changes the exponential population itself into normal.','Exponential population mean=10, SD=10 and n=100. Which approximate Xbar model applies?','Normal with centre 10 and SE 1','Exponential with rate 100','What remains exponential after applying CLT to large-sample means?','The individual-observation population','The sampling distribution of Xbar','A waiting-time population is skewed but averages 64 waits. Which object receives a normal approximation?','The average waiting time','Each waiting time','clt'),
    'C7.26':S('CLT retains the original population mean mu and uses SE sigma/sqrt(n) for Xbar.','CLT replaces the mean by zero and spread by one.','Population mean=30, sigma=8, n=16. State the CLT centre and SE.','30 and 2','0 and 1','If n increases, does the CLT centre change?','No','Yes','A non-normal process has mean 5 and SD 12; n=36. Which approximate Xbar parameters apply?','Mean 5, SE 2','Mean 0, SE 12','clt'),
    'C7.34':S('The sample proportion is p=X/n, successes divided by sample size.','The sample proportion is n/X.','48 successes occur in n=64. Find p.','0.75','1.3333','A sample has 18 failures and 42 successes. Find the success proportion.','0.70','0.30','A survey records 125 yes responses from 500. What sample statistic is used?','p=0.25','pi=125','proportion'),
    'C7.35':S('Pi denotes the fixed population proportion; p is the random sample proportion.','p is the population parameter.','A population success rate is 0.40. Which symbol denotes it?','pi','p','A sample estimates an unknown population fraction. Which quantity is the target?','pi','Xbar','A production line has a true defect proportion. Is it a statistic or parameter?','Parameter pi','Statistic p','proportion'),
    'C7.36':S('For the current proportion normal approximation, check n*pi>5 and n*(1-pi)>5.','Checking p*n after observing the sample always replaces source conditions.','n=100, pi=0.20. Do both conditions hold?','Yes','No','n=30, pi=0.10. Is the approximation supported?','No: n*pi=3','Yes: n is 30','A rare-event proportion has n*pi=4 and n*(1-pi)=196. What is the decision?','Do not use the normal approximation','Use it because one condition is large','proportion'),
    'C7.37':S('The sampling distribution of p is centred at the population proportion pi.','It is centred at the observed p for every theoretical probability.','pi=0.35. What is E(p)?','0.35','The first observed sample p','If pi stays fixed and n changes, what happens to the centre?','It stays at pi','It increases with n','Repeated polls estimate a 60% population share. Around what value do sample proportions vary?','0.60','The sample size','proportion'),
    'C7.38':S('When pi is known for a theoretical sampling distribution, SE(p)=sqrt(pi*(1-pi)/n).','Always substitute observed p into the theoretical SE.','pi=0.25 and n=100. Calculate theoretical SE.','0.0433','0.25','pi=0.50 and n=400. Calculate SE.','0.025','0.05','A probability model supplies population proportion 0.10 and n=90. Which quantity enters the SE?','pi=0.10','An invented sample p','proportion'),
    'C7.39':S('Use observed p in an estimated proportion SE only when the task asks for estimation.','Observed p always replaces known pi in theoretical probabilities.','A confidence procedure asks for estimated SE and p=0.40, n=100. Which form is used?','sqrt(0.4*0.6/100)','sqrt(pi/n) with pi omitted','A sampling probability gives known pi=0.40. Should an unrelated observed p=0.45 replace it?','No','Yes','A report explicitly says estimate the unknown proportion SE from the sample. Which value is substituted?','The observed sample p','A fixed 0.5 regardless of source','proportion'),
    'C7.40':S('Solve a sample-proportion probability by standardising p with centre pi and its sourced SE, then using the requested tail.','Treat p as a binomial count without dividing by n.','pi=0.50, n=100 and p=0.60. What z is used?','2','0.2','A p boundary is below the centre. Which sign should its z have?','Negative','Positive','The probability that a poll proportion exceeds 0.55 is required. What object is standardised?','The sample proportion p','One Bernoulli observation','proportion'),
    'C7.41':S('Central limits for p are pi plus or minus z*sqrt(pi*(1-pi)/n).','Use pi plus or minus z*pi.','pi=0.5, n=100 and z=1.96. Which approximate limits result?','0.402 to 0.598','-0.48 to 1.48','For a central 90%, which z cumulative areas define the two limits?','0.05 and 0.95','0.10 and 0.90','A survey asks where the middle 80% of sample proportions lie. What remains the centre?','pi','Observed X count','proportion'),
    'C7.42':S('A probability about p describes the random proportion obtained in a sample of size n.','It is a probability that the fixed population pi changes.','Interpret P(p>0.60)=0.08.','8% of repeated samples have a proportion above 0.60','There is an 8% chance pi is above 0.60','What does P(0.4<p<0.5) concern?','A sample proportion lying between 0.4 and 0.5','Individual binary outcomes between 0.4 and 0.5','A poll probability is reported. Which sample feature must appear in the interpretation?','The proportion in a random sample','The fixed population parameter changing','interpretation'),
    'C7.43':S('Increasing n reduces the SE of p while leaving centre pi unchanged.','Increasing n raises pi.','n is quadrupled with pi fixed. What happens to SE(p)?','It halves','It quarters','Two polls have n=100 and n=900 from the same population. Which p distribution is narrower?','n=900','n=100','A simulation increases sample size but keeps the population unchanged. What happens to sample-proportion variability?','It decreases','Its centre shifts upward','proportion')
  });
  function semanticSpec(id){const s=SKILLS[id],x=SPECIAL_SEMANTICS[id];if(x)return x;return{fact:`A valid response explicitly demonstrates: ${s.name}.`,wrong:`Ignore ${s.name} and substitute an unrelated rule.`,a1:`A solution is audited for the exact target “${s.name}”. Which response is admissible?`,a1Answer:`The response correctly demonstrates ${s.name}.`,a1Wrong:'The response uses a different method and never demonstrates the target.',a2:`Which second independent submission gives direct evidence for “${s.name}”?`,a2Answer:`A complete response that carries out ${s.name}.`,a2Wrong:'A response that merely names the surrounding chapter.',transfer:`In a changed professional context, which action still demonstrates “${s.name}”?`,transferAnswer:`Carry out ${s.name} on the new information.`,transferWrong:'Reuse an old answer without applying the target.',family:s.chapter===6?'chapter6-method':s.chapter===7?'chapter7-method':'chapter9-hypothesis'} }
  const semFlags=(role,changed=false)=>({...defaultFlags(),understandEligible:role==='U',retrievalEligible:['R1','R2'].includes(role),familiar:['A1','A2'].includes(role),changedWording:changed,alteredRepresentation:changed,unlabelled:changed,mixedEligible:true,timedEligible:true,delayedCompatible:true,repairRoles:['immediate','delayed','transfer']});
  function semanticScaffold(id,prompt,answer){return{recognise:`Target the exact skill ${id}: ${SKILLS[id].name}.`,represent:`Translate the words into the relevant object, event, formula or classification.`,select:'Choose the source-confirmed route and reject its nearest competitor.',formula:`State the governing rule before substitution.`,substitution:`Map the supplied values or labels into that rule.`,execute:`Carry out the calculation or tool step: ${prompt}`,interpret:`Answer in the terms of the random object; expected committed response: ${answer}.`,verify:'Check direction, units, order, magnitude and source conditions.'}}
  function addSemanticTask(id,role,prompt,answer,wrong,parent=null,changed=false){const s=SKILLS[id],qid=`SEM-${id.replace('.','-')}-${role}`,source=clone(s.chapter===6?SOURCE_META.ch6:s.chapter===7?SOURCE_META.ch7:SOURCE_META.ch9),number=+id.split('.')[1];if(s.chapter===7&&number>=27&&number<=33)source.pinpoint='§2.6, p. 7';const q={id:qid,chapter:s.chapter,skillIds:[id],assessesSkillIds:[id],designatedEvidenceTarget:id,source,status:'ACTIVE',validationStatus:VALIDATION,variantClass:changed?'GENERATED_VALIDATED_TRANSFER':'GENERATED_VALIDATED',parentQuestionId:parent,sourceBasis:changed?`${source.file} · ${source.pinpoint}`:null,changedDimensions:changed?['context','information order','numerical values or representation']:[],prompt,options:[answer,wrong],responseType:'choice',learningRole:role==='U'?'conceptual':role.startsWith('R')?'retrieval':'application',diagnosticDimension:role==='U'?'RECOGNITION':'UNKNOWN',answer:{type:'choice',value:answer},evidenceFlags:semFlags(role,changed),semanticTarget:id,semanticAuthenticity:'SOURCE_SPECIFIC',skillFamily:semanticSpec(id).family,scaffold:semanticScaffold(id,prompt,answer)};if(changed)VARIANTS[qid]=q;else QUESTIONS[qid]=q;return q}

  const CH9_TUTORIAL_SCOPE_EXCLUSIONS=Object.freeze(['Q15','Q16','Q19','Q20']);
  addV11Question({id:'P-C9-Z-EXCEL',chapter:9,skillIds:['C9.24'],assessesSkillIds:['C9.24'],designatedEvidenceTarget:'C9.24',source:clone(SOURCE_META.ch9),status:'ACTIVE',validationStatus:VALIDATION,variantClass:'OFFICIAL_WORKFLOW_RECONSTRUCTION',prompt:'Reconstruct the source-deck Excel formula for a two-tail Z p-value when Zcalc is in B11.',responseType:'formula',learningRole:'excel',diagnosticDimension:'PROCEDURE',requiresExcel:true,excelFamily:'EXCEL_FORMULA_RECONSTRUCTION',excelExecutionMode:'RECONSTRUCTION',answer:{type:'formula',value:'(1-NORM.S.DIST(ABS(B11),TRUE))*2',aliases:['=(1-NORM.S.DIST(ABS(B11),TRUE))*2']},evidenceFlags:{...defaultFlags(),familiar:true,retrievalEligible:true,mixedEligible:true,timedEligible:true,delayedCompatible:true},semanticTarget:'C9.24',scaffold:semanticScaffold('C9.24','Map |Zcalc| into the source two-tail Excel p-value route.','=(1-NORM.S.DIST(ABS(B11),TRUE))*2')});
  addV11Question({id:'P-C9-T-EXCEL',chapter:9,skillIds:['C9.30'],assessesSkillIds:['C9.30'],designatedEvidenceTarget:'C9.30',source:clone(SOURCE_META.ch9),status:'ACTIVE',validationStatus:VALIDATION,variantClass:'OFFICIAL_WORKFLOW_RECONSTRUCTION',prompt:'Reconstruct the source-deck Excel formula for a two-tail t p-value when tcalc is in B12 and df is in B11.',responseType:'formula',learningRole:'excel',diagnosticDimension:'PROCEDURE',requiresExcel:true,excelFamily:'EXCEL_FORMULA_RECONSTRUCTION',excelExecutionMode:'RECONSTRUCTION',answer:{type:'formula',value:'T.DIST.2T(ABS(B12),B11)',aliases:['=T.DIST.2T(ABS(B12),B11)']},evidenceFlags:{...defaultFlags(),familiar:true,retrievalEligible:true,mixedEligible:true,timedEligible:true,delayedCompatible:true},semanticTarget:'C9.30',scaffold:semanticScaffold('C9.30','Map |tcalc| and df into T.DIST.2T.','=T.DIST.2T(ABS(B12),B11)')});


  Object.assign(SPECIAL_SEMANTICS,{
    'C9.01':S('A hypothesis is a claim about a population parameter such as μ or π.','A hypothesis is written about one observed sample statistic.','Which is a hypothesis about a population parameter?','μ=4500','X̄=4500 is always H0','A survey claim says 25% of all tertiary students own a car. Which parameter statement matches?','π=0.25','p=25','A new factory claim concerns the long-run mean fill. What kind of quantity must H0 reference?','A population parameter μ','The realised sample mean only','hypothesis-foundations'),
    'C9.02':S('In the SDS188 source treatment, H0 is written with equality for the population parameter being tested.','H0 is written with ≠, < or > and H1 gets equality.','Claim: population mean is 30 mm. Write H0.','H0: μ=30','H0: X̄=30','A machine is programmed for 240 ml. Which null is source-aligned?','H0: μ=240','H0: μ≠240','A new claim says the population proportion is .40. Which null form is used?','H0: π=.40','H0: p=.40','hypothesis-foundations'),
    'C9.03':S('H0 represents the status quo/current claim to be validated and may or may not be rejected.','H0 is automatically false because a researcher prefers H1.','Which hypothesis represents the status quo claim?','H0','H1','A company currently advertises a mean of 110 minutes. Which hypothesis carries that current belief?','H0','H1 only','A new sample differs slightly from the advertised value. Does that alone erase the status quo before testing?','No','Yes','hypothesis-foundations'),
    'C9.04':S('H1 is mutually exclusive with H0 and challenges the status quo.','H1 repeats H0 using the same equality.','If H0: μ=30 and the research question asks whether the mean differs, what is H1?','H1: μ≠30','H1: μ=30','If the research claim is that the mean is below 500, which alternative matches?','H1: μ<500','H1: μ=500','A study asks whether π is greater than .5. Which alternative carries the research direction?','H1: π>.5','H1: π=.5','hypothesis-foundations'),
    'C9.05':S('The valid decisions are reject H0 or do not reject H0; the source says H0 is never accepted.','A non-significant result proves H0 true and should be written as accept H0.','p=.20 at α=.05. Which decision wording is valid?','Do not reject H0','Accept H0','A test statistic lies in the rejection region. Which decision is valid?','Reject H0','Accept H1 as certain','A new context yields weak evidence against H0. Which wording preserves the source rule?','Do not reject H0','Prove H0','decision-language'),
    'C9.06':S('Hypothesis testing begins by assuming H0 is true and asks whether the sample is sufficiently inconsistent with that assumption.','Testing begins by assuming H1 is true and trying to confirm it.','Which assumption generates the reference distribution for the test statistic?','H0 is true','H1 is true','The slides use “innocent until proven guilty.” Which hypothesis is treated as the initial position?','H0','H1','In a new test, where does μ0 in the standard error/test statistic come from?','The null hypothesis','The observed sample mean','hypothesis-foundations'),
    'C9.07':S('A Type I error is rejecting H0 when H0 is actually true; its probability is α.','A Type I error is failing to reject a false H0 and has probability β.','H0 is true but the test rejects it. Classify the error.','Type I','Type II','At α=.05, what is the probability of a Type I error under the test design?','0.05','0.95','A new quality-control test wrongly flags a correct process as changed. Which error is this?','Type I','Type II','errors-power'),
    'C9.08':S('A Type II error is failing to reject H0 when H0 is actually false; its probability is β.','A Type II error is rejecting a true H0 and has probability α.','H0 is false but the test does not reject it. Classify the error.','Type II','Type I','Which symbol denotes the Type II error probability?','β','α','A faulty process change goes undetected by the test. Which error is represented?','Type II','Type I','errors-power'),
    'C9.09':S('The confidence coefficient is 1−α.','The confidence coefficient is 1−β.','If α=.05, what is the confidence coefficient?','0.95','0.05','If α=.01, what is 1−α?','0.99','0.90','A test uses α=.10. Which complementary coefficient belongs to α?','0.90','0.10','errors-power'),
    'C9.10':S('Power is 1−β, the probability of rejecting H0 when H0 is false.','Power is 1−α, the probability that H0 is true.','If β=.20, what is power?','0.80','0.20','A test has power .95. What is β?','0.05','0.95','A new design detects a false null 90% of the time. What is its power?','0.90','0.10','errors-power'),
    'C9.11':S('For fixed n and other conditions, reducing α makes rejection harder and generally increases β.','Reducing α automatically reduces β for the same n.','For fixed n, α drops from .05 to .01. What happens to β?','β increases','β decreases','Why is there a trade-off?','A stricter rejection region lowers Type I risk but makes false H0 harder to detect','Both errors always move together downward','A new design wants lower α without larger β. What additional lever may be needed?','Increase information such as sample size','Nothing can change β','errors-power'),
    'C9.12':S('β is larger when the true parameter is closer to the null, variance is larger, or n is smaller; the opposite changes increase power.','Power decreases when the true parameter moves farther from μ0.','H0:μ=100. Which true mean is harder to detect: 90 or 75?','90','75','Holding all else fixed, what does a larger n generally do to power?','Increases power','Decreases power','A new process shift moves farther from μ0 while σ is unchanged. What happens to detectability?','It becomes easier; power increases','It becomes harder','errors-power'),
    'C9.13':S('H1: parameter≠value defines a two-tail test.','The ≠ alternative defines a one-tail upper test.','H1: μ≠500. Which tail structure is required?','Two-tail','Upper-tail only','H1: π≠.20. Where can evidence against H0 occur?','In either tail','Only the right tail','A new claim says “different from.” Which mathematical alternative matches?','≠ and two-tail','> and upper-tail','tails-alpha'),
    'C9.14':S('H1: parameter<value defines a lower-tail test.','A < alternative places the rejection region in the right tail.','H1: μ<500. Which rejection tail is used?','Lower/left tail','Upper/right tail','For a lower-tail p-value, which standard-normal area is used?','Φ(zcalc)','1−Φ(zcalc)','A new study asks whether mean lifetime fell below target. Which direction is H1?','μ<μ0','μ>μ0','tails-alpha'),
    'C9.15':S('H1: parameter>value defines an upper-tail test.','A > alternative places rejection in the left tail.','H1: μ>500. Which rejection tail is used?','Upper/right tail','Lower/left tail','For an upper-tail Z test, which probability form is used?','1−Φ(zcalc)','Φ(zcalc)','A survey asks whether more than half prefer an option. Which alternative matches?','π>.5','π<.5','tails-alpha'),
    'C9.16':S('A one-tail test puts all α in the directed tail; a two-tail test splits α/2 into each tail.','Every hypothesis test splits α/2 into both tails.','Two-tail α=.10. How much area is in each rejection tail?','0.05','0.10','Upper-tail α=.01. How much rejection area is in the upper tail?','0.01','0.005','A new two-sided test uses α=.05. Which cumulative critical areas correspond to the tails?','.025 and .975','.05 and .95','tails-alpha'),
    'C9.17':S('For a one-sample mean test with population σ known, the source selects the Z test.','If σ is known, replace it by s and use Student t.','Population σ is supplied. Which mean-test family applies?','Z test','Student t test','A manufacturer specification gives σ=.08 and n=50. Which route is source-aligned?','Known-σ Z','Unknown-σ t','In a new mean test, what single fact routes known σ to Z?','Population standard deviation σ is known','The sample size is below 30','z-testing'),
    'C9.18':S('For known σ, Z=(X̄−μ0)/(σ/√n).','For known σ, divide X̄−μ0 by σ rather than the sample-mean SE.','μ0=500, σ=120, n=36, X̄=550. Calculate Z.','2.5','0.4167','μ0=100, σ=10, n=25, X̄=104. Calculate Z.','2','0.4','A new known-σ mean test supplies X̄, μ0, σ and n. What denominator belongs in Z?','σ/√n','σ/n','z-testing'),
    'C9.19':S('Under the critical-value approach, reject H0 only when the test statistic falls in the rejection region defined by α and the tail direction.','Reject H0 whenever the test statistic is positive.','Two-tail α=.10 gives critical values about ±1.645. Z=1.20. Decide.','Do not reject H0','Reject H0','Upper-tail α=.01 has critical z≈2.326. Z=2.39. Decide.','Reject H0','Do not reject H0','A new lower-tail test has zcalc above its negative critical boundary. What is the decision?','Do not reject H0','Reject H0','z-testing'),
    'C9.20':S('The p-value is the probability, assuming H0 is true, of obtaining a test statistic equal to or more extreme than the observed result in the direction(s) of H1.','The p-value is the probability that H0 itself is true.','Which interpretation is source-aligned?','Probability of an equally or more extreme statistic assuming H0','Probability H0 is correct','If the observed statistic is more extreme, what usually happens to the p-value?','It becomes smaller','It becomes larger','A new report says p=.03. What assumption underlies that probability calculation?','H0 is true','H1 is proven true','p-value'),
    'C9.21':S('Using the p-value approach, reject H0 when p<α; otherwise do not reject H0.','Reject H0 when p>α.','p=.0455 and α=.05. Decide.','Reject H0','Do not reject H0','p=.0838 and α=.01. Decide.','Do not reject H0','Reject H0','A new test gives p=.12 at α=.10. Which decision is correct?','Do not reject H0','Accept H0','p-value'),
    'C9.22':S('For a two-tail Z test, the p-value doubles the tail area beyond |Zcalc|: 2[1−Φ(|z|)].','A two-tail p-value is just Φ(zcalc) regardless of sign.','Z=2.00 in a two-tail test. Approximate p.','0.0455','0.0228','Z=−1.38 in a two-tail test. Approximate p.','0.1676','0.0838','A new two-tail Z is −2.20. Which structural p-value formula applies?','2[1−Φ(2.20)]','Φ(−2.20)','p-value'),
    'C9.23':S('A one-tail Z p-value uses the probability in the directed tail only; it is not doubled.','Every p-value must be doubled.','Lower-tail Z=−1.38. Approximate p.','0.0838','0.1676','Upper-tail Z=1.64. Which form applies?','1−Φ(1.64)','2[1−Φ(1.64)]','A new lower-tail test has zcalc negative. Which area is the p-value?','Cumulative left area Φ(zcalc)','Right area 1−Φ(zcalc)','p-value'),
    'C9.24':S('The source Excel Z workflow uses NORM.S.INV for critical values and NORM.S.DIST for cumulative probabilities; the shown two-tail p formula is (1−NORM.S.DIST(ABS(z),TRUE))*2.','The source computes a two-tail Z p-value with T.DIST.2T.','Which source formula gives a two-tail Z p-value from B11?','=(1-NORM.S.DIST(ABS(B11),TRUE))*2','=T.DIST.2T(ABS(B11),B10)','Which function family gives standard-normal critical values?','NORM.S.INV','T.INV','A new workbook has zcalc in D8. Which structural formula matches the source two-tail route?','=(1-NORM.S.DIST(ABS(D8),TRUE))*2','=NORM.S.DIST(D8,TRUE)','excel-z'),
    'C9.25':S('For the same α/confidence level, a two-tail mean test and its matching confidence interval give consistent decisions about μ0.','A matching CI and two-tail test should routinely contradict each other.','The 99% CI includes μ0. What matches a two-tail α=.01 test?','Do not reject H0','Reject H0','The matching CI excludes μ0. What test decision follows?','Reject H0','Accept H0','A new two-sided test is non-significant at 5%. Where should μ0 lie relative to the matching 95% CI?','Inside the interval','Necessarily outside','ci-test-bridge'),
    'C9.26':S('For a one-sample mean test with population σ unknown and sample s available, the source selects Student t.','Unknown σ still uses Z with s inserted as if it were σ.','Population σ is unknown; s is supplied. Which test family applies?','Student t','Z','n=25, sample s=216, normal population assumption stated. Which route applies?','t test','known-σ Z test','A new mean question gives sample SD only. Which clue selects t?','σ is unknown and s estimates spread','The sample mean is nonzero','t-testing'),
    'C9.27':S('For unknown σ, T=(X̄−μ0)/(s/√n).','The t statistic divides by s rather than s/√n.','μ0=1500, X̄=1577, s=216, n=25. Approximate T.','1.7824','0.3565','μ0=50, X̄=47, s=8, n=16. Calculate T.','-1.5','-0.375','A new t test supplies s and n. What denominator is required?','s/√n','s/n','t-testing'),
    'C9.28':S('For the one-sample t test in the source, df=n−1.','The degrees of freedom are always n.','n=25. Find df.','24','25','n=13. Find df.','12','13','A new sample contains 40 observations. What df enters T.DIST/T.INV?','39','40','t-testing'),
    'C9.29':S('The source requires the population to be approximately normal for the small-sample one-sample t procedures shown; serious violations can undermine validity.','Normality never matters for any t test regardless of sample size or outliers.','n=13 and the source example states lifetimes are normal. Why is that statement relevant?','It supports the t-test distributional condition','It turns s into σ','A new small sample is extremely skewed with severe outliers. What should you do?','Question the t-test assumption/validity','Ignore the shape entirely','Which source objective accompanies test procedures?','Evaluate assumptions and consequences of serious violations','Assumptions are optional','t-testing'),
    'C9.30':S('For t tests, select critical values and p-values with the t distribution and df=n−1; the source shows T.INV, T.DIST and T.DIST.2T routes.','Use NORM.S.DIST for every t-test p-value.','df=24, upper-tail α=.10. Which critical distribution is used?','Student t with df=24','Standard normal regardless of s','Which source Excel function gives a two-tail t p-value?','T.DIST.2T','NORM.S.DIST','A new two-tail t test has |tcalc| and df. Which Excel route matches?','=T.DIST.2T(ABS(tcalc),df)','=NORM.S.DIST(tcalc,TRUE)','t-testing'),
    'C9.31':S('For one-tail teaching examples, SDS188 writes H0 with equality and places the direction in H1.','SDS188 places the directional inequality in H0 and equality in H1.','Claim: mean is greater than 1500. Which pair matches the source convention?','H0: μ=1500; H1: μ>1500','H0: μ>1500; H1: μ=1500','Claim: mean life is below 500. Which pair matches?','H0: μ=500; H1: μ<500','H0: μ<500; H1: μ=500','A new one-tail claim says π>.5. Where is the direction written?','In H1','In H0 only','tails-alpha'),
    'C9.32':S('A one-proportion hypothesis test applies to binary/categorical success-failure data and tests population proportion π.','A one-proportion test is used for a continuous population mean.','Defective/not defective outcomes. Which parameter is tested?','Population proportion π','Population mean μ','Prefer R100/day off responses are binary. Which test family fits a single claimed population share?','One-proportion Z test','One-sample t mean test','A new yes/no survey is analysed. What type of data structure supports the proportion test?','Binary categorical outcomes','Continuous measurements only','proportion-testing'),
    'C9.33':S('The sample proportion is p=x/n, where x is the number of successes.','The sample proportion is n/x.','x=88 and n=400. Calculate p.','0.22','4.545','x=593 and n=1040. Approximate p.','0.5702','0.5','A new survey has 75 yes responses out of 300. What is p?','0.25','4','proportion-testing'),
    'C9.34':S('Before the normal approximation proportion test, the source checks nπ0≥5 and n(1−π0)≥5 using the null proportion.','The checks use observed p only and require n≥30 instead.','n=400 and π0=.20. What are the expected counts?','80 and 320','88 and 312','n=20 and π0=.10. Is the source approximation condition met?','No; nπ0=2','Yes because n is 20','A new H0 uses π0=.5 and n=30. Do both checks pass?','Yes; 15 and 15','No','proportion-testing'),
    'C9.35':S('The one-proportion Z statistic is (p−π0)/sqrt[π0(1−π0)/n].','Use observed p in both numerator and null standard error so the null disappears.','p=.22, π0=.20, n=400. Calculate Z.','1','0.02','p=.60, π0=.50, n=100. Calculate Z.','2','0.2','A new proportion test supplies π0. Which value belongs in the standard error?','π0','Only observed p','proportion-testing'),
    'C9.36':S('After computing the proportion Z statistic, apply the same tail/critical-value or p-value logic dictated by H1 and α.','A proportion test always uses a two-tail decision regardless of H1.','H1:π>.5 and zcalc=4.53 at α=.05. Decide.','Reject H0','Do not reject H0','H1:π<.2 and the lower-tail p=.12 at α=.05. Decide.','Do not reject H0','Reject H0','A new proportion test uses p-value .03 and α=.01. What is the decision?','Do not reject H0','Reject H0','proportion-testing'),
    'C9.37':S('Statistical significance does not automatically imply practical importance; very large samples can make tiny effects statistically significant.','Every statistically significant effect is necessarily important in practice.','A huge n finds a trivial 0.01-unit difference with p<.001. What additional question is needed?','Is the effect practically meaningful?','Is H0 now mathematically impossible?','A small sample misses a substantively large effect. What may be relevant?','Low power may have limited detection','Practical importance is zero','A new report gives only p-values. What should also be considered?','Effect size/context and practical importance','Nothing else','responsibility'),
    'C9.38':S('Responsible hypothesis-test planning considers the study goal, hypotheses, tail, random sampling, data type, α, sample size/power, procedure and interpretation; ethical reporting includes pertinent non-significant results.','Choose hypotheses, α and which results to report after seeing which outcomes are significant.','Which action belongs before data analysis?','Choose the intended hypotheses/test design and significance level','Choose α after seeing p','Which reporting practice is ethical?','Report pertinent findings, including non-significant ones','Suppress all non-significant findings','A new study cannot obtain a random sample. What should the analyst do?','Recognise and disclose the design limitation','Pretend the sampling assumption holds','responsibility'),
    'C9.39':S('Power generally rises when α increases, the true parameter is farther from the null, or a correctly specified one-tail test concentrates α in the relevant direction.','Power always rises when α decreases and the alternative moves closer to H0.','Holding n fixed, which α usually gives more power: .05 or .01?','.05','.01','True μ moves farther from μ0. What happens to power?','It increases','It decreases','If direction was legitimately specified in advance, how can a one-tail test compare with a two-tail test?','It can have greater power in that direction','It always has less power','power'),
    'C9.40':S('To calculate β and power for a mean test: find the critical sample-mean boundary under H0, compute the non-rejection probability under the specified true mean, then use power=1−β.','Calculate β from the H0 distribution only and stop before using the true mean.','Tutorial Q21 with true μ=197 gives power about what?','0.6761','0.3239','For the same test with true μ=194, power is approximately what?','0.9947','0.0053','A new lower-tail test gives β=.12 at a specified true mean. What is power?','0.88','0.12','power')
  });

